}

func aggregateEvidenceUsefulText(text string) bool {
	if len(text) < 3 {
		return false
	}
	lower := strings.ToLower(text)
	switch lower {
	case "true", "false", "<nil>":
		return false
	}
	if strings.HasPrefix(lower, "path:") || strings.HasPrefix(lower, "named_memory:") || strings.HasPrefix(lower, "memory_claim:") {
		return false
	}
	return true
}

