var contextQueryTokenPattern = regexp.MustCompile(`(?i)\$?\d+(?:\.\d+)?|[a-z][a-z0-9'-]*`)

var contextQuestionStopwords = map[string]bool{
	"a": true, "an": true, "and": true, "are": true, "as": true, "at": true,
