	ClaimStatusRejected          ClaimStatus = "rejected"
)

// IsValid reports whether s is a known ClaimStatus.
func (s ClaimStatus) IsValid() bool {
	switch s {
	case ClaimStatusCandidate, ClaimStatusCurrent, ClaimStatusNeedsRevalidation,
