```go
// promoteCandidateClaimsForRefs promotes candidate claims whose every SourceRef
// appears in refs. It is best-effort: individual transition or persistence
// failures are ignored so that one bad claim does not block the rest.
func promoteCandidateClaimsForRefs(ctx context.Context, store InvalidationStore, workspaceID string, refs []EvidenceRef, reason string, now time.Time) {
	acceptedSet := make(map[string]bool, len(refs))
	for _, ref := range refs {
		acceptedSet[FormatEvidenceRef(ref)] = true
	}
	claims, _ := store.ListClaims(ctx, ClaimFilter{
		WorkspaceID: workspaceID,
		Status:      ClaimStatusCandidate,
	})
	for _, claim := range claims {
		if len(claim.SourceRefs) == 0 {
			continue
		}
		allMatch := true
		for _, sr := range claim.SourceRefs {
			if !acceptedSet[FormatEvidenceRef(sr)] {
				allMatch = false
				break
			}
		}
		if !allMatch {
			continue
		}
		promoted, err := ApplyClaimTransition(claim, ClaimStatusCurrent, reason, now)
		if err == nil {
			if _, upsertErr := store.UpsertClaim(ctx, promoted); upsertErr != nil {
				_ = upsertErr // best-effort promotion
			}
		}
	}
}
```

