func splitEvalModes(raw []string) []string {
	out := make([]string, 0, len(raw))
	for _, value := range raw {
		for _, piece := range strings.Split(value, ",") {
			piece = strings.TrimSpace(piece)
			if piece != "" {
				out = append(out, piece)
			}
		}
	}
	return out
}

func resolveLongmemWorkspaceID(cfg config.Config, workspacePath, workspaceID string) (string, error) {
	if id := strings.TrimSpace(workspaceID); id != "" {
		return id, nil
	}
	if path := strings.TrimSpace(workspacePath); path != "" {
		return workspaceutil.CanonicalID(path), nil
	}
	if root := strings.TrimSpace(cfg.Storage.Root); root != "" {
		return workspaceutil.CanonicalID(root), nil
	}
	return "", fmt.Errorf("workspace_id (or --workspace path) is required")
}

func openEvalMemoryStore(ctx context.Context, cfg config.Config) (storage.MemoryStore, error) {
	return memorystore.OpenWithConfig(ctx, cfg)
}

func openEvalQueueStore(ctx context.Context, cfg config.Config) (*embedding.Store, error) {
	return embedding.OpenStoreFromConfig(ctx, cfg)
}

func longmemModesInclude(modes []longmemeval.Mode, want longmemeval.Mode) bool {
	for _, mode := range modes {
		if mode == want {
			return true
		}
	}
	return false
}

type longmemRLMAnswerRunnerConfig struct {
	AppConfig     config.Config
	WorkspaceRoot string
	Provider      string
	Model         string
	BaseURL       string
	APIKey        string
	Timeout       time.Duration
	MaxIterations int
	RouteProfile  string
	PlanMode      string
	ToolProfile   string
	Strategy      longmemAnswerStrategy
}

func newLongmemRLMAnswerRunner(in longmemRLMAnswerRunnerConfig) longmemeval.AnswerRunner {
	return func(ctx context.Context, req longmemeval.AnswerRequest) (longmemeval.AnswerResult, error) {
		strategy := in.Strategy
		if strategy == "" {
			strategy = longmemAnswerStrategyRetrieveMemory
		}
		timeout := in.Timeout
		if timeout <= 0 {
			timeout = 90 * time.Second
		}
		maxIterations := in.MaxIterations
		if maxIterations <= 0 {
			maxIterations = 5
		}
		toolProfile := strings.TrimSpace(in.ToolProfile)
		if toolProfile == "" {
			toolProfile = string(strategy.defaultToolProfile())
		}
		routeProfile := strings.TrimSpace(in.RouteProfile)
		if routeProfile == "" {
			routeProfile = string(strategy.defaultRouteProfile())
		}
		planMode := strings.TrimSpace(in.PlanMode)
		if planMode == "" {
			planMode = string(strategy.defaultPlanMode())
		}
		workspaceRoot := strings.TrimSpace(in.WorkspaceRoot)
		if workspaceRoot == "" {
			workspaceRoot = req.WorkspaceID
		}

		runCtx, cancel := context.WithTimeout(ctx, timeout)
		defer cancel()

		companionDB, companionClose, err := openRLMCompanionDB(runCtx, in.AppConfig)
		if err != nil {
			return longmemeval.AnswerResult{}, err
		}
		if companionClose != nil {
			defer func() { _ = companionClose() }()
		}

		prompt := longmemAnswerPrompt(req.Question, strategy)
		task := rlm.Task{
			Prompt:        prompt,
			WorkspaceRoot: workspaceRoot,
			WorkspaceID:   req.WorkspaceID,
			MaxIterations: maxIterations,
			Metadata: map[string]any{
				"longmem_case_id":         strings.TrimSpace(req.CaseID),
				"longmem_limit":           req.Limit,
				"longmem_answer_strategy": string(strategy),
			},
		}
		bootstrapper := rlmenv.NewBootstrapper(rlmenv.BootstrapConfig{
			AppConfig:   in.AppConfig,
			CompanionDB: companionDB,
		})
		env, err := bootstrapper.Build(runCtx, task)
		if err != nil {
			return longmemeval.AnswerResult{}, err
		}
		defer func() { _ = bootstrapper.Close() }()
		env.Tools = rlmenv.FilterTools(env.Tools, toolProfile)

		adapter := rlmenv.NewReadOnlyAdapter(in.AppConfig, workspaceRoot, "", companionDB, env)
		adapter.SetWorkspaceID(req.WorkspaceID)
		adapter.SetContextEngineStore(bootstrapper.ContextEngineStore())
		adapter.SetTaskStore(bootstrapper.TaskStore())
		recorder := &longmemAnswerToolRecorder{next: adapter}

		llmCfg := buildRLMCLIConfig(rlmCLIConfigInput{
			Task:        task,
			Provider:    in.Provider,
			Model:       in.Model,
			BaseURL:     in.BaseURL,
			APIKey:      in.APIKey,
			Timeout:     timeout,
			ToolProfile: toolProfile,
		})
		llmCfg.MaxIterations = maxIterations
		llmCfg.RequireToolUse = len(env.Tools) > 0
		llmCfg.RouteProfile = rlm.NormalizeRouteProfile(routeProfile)
		llmCfg.PlanMode = rlm.NormalizePlanMode(planMode)
		runner := rlm.LLMRunner{
			Config: llmCfg,
			Tools:  recorder,
		}

		started := time.Now()
		rlmResult, err := runner.Run(runCtx, task, env)
		out := longmemeval.AnswerResult{
			Method:        "rlm-answer",
			DurationMS:    time.Since(started).Milliseconds(),
			EvidenceNames: recorder.evidenceNames(),
			EvidenceRefs:  recorder.evidenceRefs(),
		}
		if err != nil {
			return out, err
		}
		out.Answer = strings.TrimSpace(rlmResult.Answer)
		out.Iterations = rlmResult.Iterations
		out.ToolNames = evalStringsFromAnySlice(rlmResult.Metadata["tool_names"])
		if len(out.ToolNames) == 0 {
			out.ToolNames = collectRLMPhaseToolNames(rlmResult.Metadata)
		}
		out.EvidenceRefs = uniqueEvalStrings(append(out.EvidenceRefs, rlmResult.EvidenceRefs...))
		return out, nil
	}
}

type longmemAnswerStrategy string

const (
	longmemAnswerStrategyRetrieveMemory longmemAnswerStrategy = "retrieve-memory"
	longmemAnswerStrategyGatherMemory   longmemAnswerStrategy = "gather-memory"
	longmemAnswerStrategyGatherMixed    longmemAnswerStrategy = "gather-mixed"
	longmemAnswerStrategyFullDebug      longmemAnswerStrategy = "full-debug"
)

type longmemAnswerRuntimeInput struct {
	Strategy            string
	RouteProfile        string
	PlanMode            string
	ToolProfile         string
	RouteProfileChanged bool
	PlanModeChanged     bool
	ToolProfileChanged  bool
}

type longmemAnswerRuntime struct {
	Strategy     longmemAnswerStrategy
	RouteProfile string
	PlanMode     string
	ToolProfile  string
}

func resolveLongmemAnswerRuntime(in longmemAnswerRuntimeInput) (longmemAnswerRuntime, error) {
	strategy, err := normalizeLongmemAnswerStrategy(in.Strategy)
	if err != nil {
		return longmemAnswerRuntime{}, err
	}
	out := longmemAnswerRuntime{
		Strategy:     strategy,
		RouteProfile: string(strategy.defaultRouteProfile()),
		PlanMode:     string(strategy.defaultPlanMode()),
		ToolProfile:  string(strategy.defaultToolProfile()),
	}
	if in.RouteProfileChanged || strings.TrimSpace(in.RouteProfile) != "" {
		out.RouteProfile = strings.TrimSpace(in.RouteProfile)
	}
	if in.PlanModeChanged || strings.TrimSpace(in.PlanMode) != "" {
		out.PlanMode = strings.TrimSpace(in.PlanMode)
	}
	if in.ToolProfileChanged || strings.TrimSpace(in.ToolProfile) != "" {
		out.ToolProfile = strings.TrimSpace(in.ToolProfile)
	}
	if out.RouteProfile == "" {
		out.RouteProfile = string(strategy.defaultRouteProfile())
	}
	if out.PlanMode == "" {
		out.PlanMode = string(strategy.defaultPlanMode())
	}
	if out.ToolProfile == "" {
		out.ToolProfile = string(strategy.defaultToolProfile())
	}
	return out, nil
}

func normalizeLongmemAnswerStrategy(value string) (longmemAnswerStrategy, error) {
	switch strings.ToLower(strings.TrimSpace(value)) {
	case "", string(longmemAnswerStrategyRetrieveMemory), "memory", "retrieve_memory":
		return longmemAnswerStrategyRetrieveMemory, nil
	case string(longmemAnswerStrategyGatherMemory), "gather_memory":
		return longmemAnswerStrategyGatherMemory, nil
	case string(longmemAnswerStrategyGatherMixed), "gather_mixed":
		return longmemAnswerStrategyGatherMixed, nil
	case string(longmemAnswerStrategyFullDebug), "full_debug":
		return longmemAnswerStrategyFullDebug, nil
	default:
		return "", fmt.Errorf("unknown longmem answer strategy %q", value)
	}
}

func (s longmemAnswerStrategy) defaultRouteProfile() rlm.RouteProfile {
	switch s {
	case longmemAnswerStrategyGatherMixed, longmemAnswerStrategyFullDebug:
		return rlm.RouteProfileMixed
	default:
		return rlm.RouteProfileMemoryRecall
	}
}

func (s longmemAnswerStrategy) defaultPlanMode() rlm.PlanMode {
	return rlm.PlanModeFree
}

func (s longmemAnswerStrategy) defaultToolProfile() rlm.ToolProfile {
	switch s {
	case longmemAnswerStrategyGatherMemory:
		return rlm.ToolProfileGatherContext
	case longmemAnswerStrategyGatherMixed:
		return rlm.ToolProfileMemoryContext
	case longmemAnswerStrategyFullDebug:
		return rlm.ToolProfileFullDebug
	default:
		return rlm.ToolProfileMemoryRecall
	}
}

func longmemAnswerPrompt(question string, strategy longmemAnswerStrategy) string {
	question = strings.TrimSpace(question)
	switch strategy {
	case longmemAnswerStrategyGatherMemory:
		return strings.TrimSpace(`Answer the LongMem recall question using the available context tools.
Start with gather_memory_context using the question as the query. Read evidence_digest claims and slots before loading refs. Then call aggregate_evidence_refs on the smallest candidate ref set from evidence_digest.load_refs or path_set, followed by evidence_ledger on that same small ref set. Answer only from evidence_ledger accepted_rows. If evidence_ledger reports needs_fallback=true, use gather_memory_context once more with the best fallback query or narrower required_evidence from the missing answer slot, then rebuild the ledger. Load only refs the ledger leaves ambiguous, using max_tokens around 1200 for verification. Do not mention tool internals.

Question: ` + question)
	case longmemAnswerStrategyGatherMixed:
		return strings.TrimSpace(`Answer the LongMem recall question using the available memory and ContextWiki tools.
Start with plan_context_query using the question, lanes=["memory","context"], and goal="recall". Then call gather_context with the returned gather_context fields. Build evidence_ledger from candidate refs in answer_seed/path_set/evidence_digest before answering. Use retrieve_memory or retrieve_context only as follow-up diagnostics when the planned gather, evidence ledger, and one fallback probe are missing decisive evidence. Do not mention tool internals.

Question: ` + question)
	case longmemAnswerStrategyFullDebug:
		return strings.TrimSpace(`Answer the LongMem recall question using the available retrieval tools.
Start with plan_context_query using the question and goal="recall". Then call gather_context with the returned gather_context fields. Build evidence_ledger from candidate refs before final synthesis. Use retrieve_memory, retrieve_context, retrieve_mixed, or load_evidence_ref only when needed to resolve ambiguity after the planned gather and ledger. Do not use code retrieval unless the question explicitly asks about foxctl implementation. Do not mention tool internals.

Question: ` + question)
	default:
		return strings.TrimSpace(`Answer the LongMem recall question using the available memory-recall tools.
Use retrieve_memory before answering. Do not mention tool internals.

Question: ` + question)
	}
}

type longmemAnswerToolRecorder struct {
	next      rlm.ToolExecutor
	seenNames map[string]struct{}
	seenRefs  map[string]struct{}
	names     []string
	refs      []string
}

func (r *longmemAnswerToolRecorder) Execute(ctx context.Context, name string, args json.RawMessage) (map[string]any, error) {
	if r == nil || r.next == nil {
		return nil, fmt.Errorf("longmem answer tool recorder is not configured")
	}
	out, err := r.next.Execute(ctx, name, args)
	if err != nil {
		return out, err
	}
	r.recordMemoryEvidence(name, out)
	return out, nil
}

func (r *longmemAnswerToolRecorder) recordMemoryEvidence(toolName string, payload map[string]any) {
	if strings.TrimSpace(toolName) == "evidence_ledger" {
		r.recordAcceptedLedgerEvidence(payload)
		return
	}
	collectLongmemMemoryEvidence(payload, r.addName, r.addRef)
	for _, node := range longmemEvidenceNodes(payload["nodes"]) {
		refType := strings.TrimSpace(fmt.Sprint(node["ref_type"]))
		if refType != "" && !longmemMemoryEvidenceRefType(refType) {
			continue
		}
		refValue := strings.TrimSpace(fmt.Sprint(node["ref_value"]))
		if refValue != "" {
			r.addName(refValue)
		}
		ref := strings.TrimSpace(fmt.Sprint(node["ref"]))
		if ref != "" {
			r.addRef(ref)
		}
	}
}

func (r *longmemAnswerToolRecorder) recordAcceptedLedgerEvidence(payload map[string]any) {
	for _, ref := range longmemStringSlice(payload["accepted_refs"]) {
		recordLongmemMemoryRefString(ref, r.addName, r.addRef)
	}
	for _, row := range longmemMapSlice(payload["accepted_rows"]) {
		collectLongmemMemoryEvidence(row, r.addName, r.addRef)
	}
}

func collectLongmemMemoryEvidence(value any, addName func(string), addRef func(string)) {
	switch v := value.(type) {
	case string:
		recordLongmemMemoryRefString(v, addName, addRef)
	case []any:
		for _, item := range v {
			collectLongmemMemoryEvidence(item, addName, addRef)
		}
	case []map[string]any:
		for _, item := range v {
			collectLongmemMemoryEvidence(item, addName, addRef)
		}
	case map[string]any:
		refType := strings.TrimSpace(fmt.Sprint(firstMapValue(v, "ref_type", "type")))
		refValue := strings.TrimSpace(fmt.Sprint(firstMapValue(v, "ref_value", "ref")))
		if longmemMemoryEvidenceRefType(refType) && refValue != "" {
			addName(refValue)
			addRef(refType + ":" + refValue)
		}
		for _, child := range v {
			collectLongmemMemoryEvidence(child, addName, addRef)
		}
	}
}

func longmemStringSlice(value any) []string {
	switch typed := value.(type) {
	case []string:
		return typed
	case []any:
		out := make([]string, 0, len(typed))
		for _, item := range typed {
			if value := strings.TrimSpace(fmt.Sprint(item)); value != "" && value != "<nil>" {
				out = append(out, value)
			}
		}
		return out
	default:
		return nil
	}
}

func longmemMapSlice(value any) []map[string]any {
	switch typed := value.(type) {
	case []map[string]any:
		return typed
	case []any:
		out := make([]map[string]any, 0, len(typed))
		for _, item := range typed {
			if mapped, ok := item.(map[string]any); ok {
				out = append(out, mapped)
			}
		}
		return out
	default:
		return nil
	}
}

func firstMapValue(m map[string]any, keys ...string) any {
	for _, key := range keys {
		if value, ok := m[key]; ok {
			return value
		}
	}
	return nil
}

func recordLongmemMemoryRefString(value string, addName func(string), addRef func(string)) {
	value = strings.TrimSpace(value)
	for _, prefix := range []string{"memory_claim:", "named_memory:"} {
		if !strings.HasPrefix(value, prefix) {
			continue
		}
		name := strings.TrimSpace(strings.TrimPrefix(value, prefix))
		if name == "" {
			return
		}
		name = normalizeLongmemMemoryName(name)
		addName(name)
		addRef(prefix + name)
		return
	}
}

func longmemMemoryEvidenceRefType(refType string) bool {
	switch strings.TrimSpace(refType) {
	case "memory_claim", "named_memory":
		return true
	default:
		return false
	}
}

func normalizeLongmemMemoryName(name string) string {
	name = strings.TrimSpace(name)
	if name == "" || strings.HasPrefix(name, "longmem://") {
		return name
	}
	if slash := strings.LastIndex(name, "/"); slash >= 0 && slash+1 < len(name) {
		name = name[slash+1:]
	}
	if looksLikeLongmemMemoryDigest(name) {
		return "longmem://" + name
	}
	return name
}

func looksLikeLongmemMemoryDigest(value string) bool {
	if len(value) != 24 {
		return false
	}
	for _, ch := range value {
		if (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F') {
			continue
		}
		return false
	}
	return true
}

func longmemEvidenceNodes(value any) []map[string]any {
	switch nodes := value.(type) {
	case []map[string]any:
		return nodes
	case []any:
		out := make([]map[string]any, 0, len(nodes))
		for _, node := range nodes {
			if m, ok := node.(map[string]any); ok {
				out = append(out, m)
			}
		}
		return out
	default:
		return nil
	}
}

func (r *longmemAnswerToolRecorder) addName(name string) {
	name = normalizeLongmemMemoryName(name)
	if name == "" {
		return
	}
	if r.seenNames == nil {
		r.seenNames = make(map[string]struct{})
	}
	if _, ok := r.seenNames[name]; ok {
		return
	}
	r.seenNames[name] = struct{}{}
	r.names = append(r.names, name)
}

func (r *longmemAnswerToolRecorder) addRef(ref string) {
	ref = normalizeLongmemMemoryEvidenceRef(ref)
	if ref == "" {
		return
	}
	if r.seenRefs == nil {
		r.seenRefs = make(map[string]struct{})
	}
	if _, ok := r.seenRefs[ref]; ok {
		return
	}
	r.seenRefs[ref] = struct{}{}
	r.refs = append(r.refs, ref)
}

func normalizeLongmemMemoryEvidenceRef(ref string) string {
	ref = strings.TrimSpace(ref)
	for _, prefix := range []string{"memory_claim:", "named_memory:"} {
		if !strings.HasPrefix(ref, prefix) {
			continue
		}
		name := normalizeLongmemMemoryName(strings.TrimPrefix(ref, prefix))
		if name == "" {
			return ""
		}
		return prefix + name
	}
	return ref
}

func (r *longmemAnswerToolRecorder) evidenceNames() []string {
	if r == nil {
		return nil
	}
	return append([]string(nil), r.names...)
}

func (r *longmemAnswerToolRecorder) evidenceRefs() []string {
	if r == nil {
		return nil
	}
	return append([]string(nil), r.refs...)
}

func uniqueEvalStrings(values []string) []string {
	seen := make(map[string]struct{}, len(values))
	out := make([]string, 0, len(values))
	for _, value := range values {
		value = strings.TrimSpace(value)
		if value == "" {
			continue
		}
		if _, ok := seen[value]; ok {
			continue
		}
		seen[value] = struct{}{}
		out = append(out, value)
	}
	return out
}

package env

import (
	"context"
	"database/sql"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/joshka0/foxctl/internal/context/contextengine"
	"github.com/joshka0/foxctl/internal/context/contextplane"
	"github.com/joshka0/foxctl/internal/intelligence/indexing/repoindex"
	"github.com/joshka0/foxctl/internal/intelligence/repoquery"
	"github.com/joshka0/foxctl/internal/platform/config"
	ws "github.com/joshka0/foxctl/internal/platform/workspace"
	"github.com/joshka0/foxctl/internal/rlm"
	ctxengstore "github.com/joshka0/foxctl/internal/storage/contextengine"
	"github.com/joshka0/foxctl/internal/storage/obsidianindex"
	"github.com/joshka0/foxctl/internal/storage/tasks"
	"github.com/joshka0/foxctl/internal/storage/trajectory"
)

const (
	defaultRepoHandleLimit  = 5
	defaultVaultHandleLimit = 5
	defaultThreadLimit      = 5
	defaultArtifactLimit    = 5
)

// BootstrapConfig configures the environment bootstrap.
type BootstrapConfig struct {
	AppConfig        config.Config
	VaultPath        string
	CompanionDB      *sql.DB
	RepoHandleLimit  int
	VaultHandleLimit int
	ThreadLimit      int
	ArtifactLimit    int
}

// Bootstrapper builds a typed read-only RLM environment from current foxctl state.
type Bootstrapper struct {
	cfg       BootstrapConfig
	ceStore   ctxengstore.Store
	taskStore tasks.Store
}

// NewBootstrapper creates a new environment bootstrapper.
func NewBootstrapper(cfg BootstrapConfig) *Bootstrapper {
	if cfg.RepoHandleLimit <= 0 {
		cfg.RepoHandleLimit = defaultRepoHandleLimit
	}
	if cfg.VaultHandleLimit <= 0 {
		cfg.VaultHandleLimit = defaultVaultHandleLimit
	}
	if cfg.ThreadLimit <= 0 {
		cfg.ThreadLimit = defaultThreadLimit
	}
	if cfg.ArtifactLimit <= 0 {
		cfg.ArtifactLimit = defaultArtifactLimit
	}
	return &Bootstrapper{cfg: cfg}
}

// ContextEngineStore returns the lazily-opened contextengine SQLite store.
// Returns nil before Build has been called or if the store could not be opened.
// Lifetime is owned by the Bootstrapper; call Close to release it.
func (b *Bootstrapper) ContextEngineStore() ctxengstore.Store {
	return b.ceStore
}

// TaskStore returns the lazily-opened tasks SQLite store. Returns nil before
// Build has been called or if the store could not be opened. Lifetime is
// owned by the Bootstrapper; call Close to release it.
func (b *Bootstrapper) TaskStore() tasks.Store {
	return b.taskStore
}

// Close releases bootstrapper-owned resources. Safe to call multiple times.
func (b *Bootstrapper) Close() error {
	if b == nil {
		return nil
	}
	var firstErr error
	if b.ceStore != nil {
		if err := b.ceStore.Close(); err != nil && firstErr == nil {
			firstErr = err
		}
		b.ceStore = nil
	}
	if b.taskStore != nil {
		if err := b.taskStore.Close(); err != nil && firstErr == nil {
			firstErr = err
		}
		b.taskStore = nil
	}
	return firstErr
}

// Build prepares an RLM environment from ContextWiki, repo index, vault index, and optional companion state.
func (b *Bootstrapper) Build(ctx context.Context, task rlm.Task) (rlm.Environment, error) {
	env := rlm.Environment{
		Tools: DefaultTools(),
	}

	// Open the contextengine store (best-effort; errors do not fail bootstrap).
	if b.ceStore == nil && strings.TrimSpace(b.cfg.AppConfig.Storage.Root) != "" {
		if store, err := ctxengstore.Open(ctx, b.cfg.AppConfig.Storage.Root); err == nil {
			b.ceStore = store
		}
	}

	// Open the tasks store (best-effort; errors do not fail bootstrap).
	if b.taskStore == nil && strings.TrimSpace(b.cfg.AppConfig.Storage.Root) != "" {
		if store, err := tasks.Open(ctx, b.cfg.AppConfig.Storage.Root); err == nil {
			b.taskStore = store
		}
	}

	workspaceRoot := ws.Normalize(strings.TrimSpace(task.WorkspaceRoot))
	if workspaceRoot == "" {
		return env, nil
	}
	store := contextplane.NewWorkspaceStore(workspaceRoot)
	layout := store.Layout()

	top, err := readJSONFile(layout.TopOfMindPath)
	if err != nil {
		return env, err
	}
	env.TopOfMind = top

	handoff, handoffRefs, err := latestHandoff(layout.HandoffsDir)
	if err != nil {
		return env, err
	}
	env.LatestHandoff = handoff
	env.ArtifactHandles = uniqueStrings(append(env.ArtifactHandles, handoffRefs...))
	env.ArtifactHandles = uniqueStrings(append(env.ArtifactHandles, topOfMindRefs(top)...))

	threadIDs, sceneHandles, err := loadCompanionHandles(ctx, b.cfg.CompanionDB, b.cfg.ThreadLimit)
	if err != nil {
		return env, err
	}
	env.ActiveThreadIDs = threadIDs
	env.SceneHandles = sceneHandles

	repoHandles, err := b.loadRepoHandles(ctx, workspaceRoot, firstNonEmpty(task.Prompt, fmt.Sprint(top["objective"])))
	if err != nil {
		return env, err
	}
	env.RepoHandles = repoHandles

	vaultHandles, err := b.loadVaultHandles(ctx, firstNonEmpty(task.Prompt, fmt.Sprint(top["objective"])))
	if err != nil {
		return env, err
	}
	env.VaultHandles = vaultHandles

	artifactHandles, err := b.loadTrajectoryHandles(ctx, workspaceRoot)
	if err != nil {
		return env, err
	}
	env.ArtifactHandles = uniqueStrings(append(env.ArtifactHandles, artifactHandles...))

	return env, nil
}

func (b *Bootstrapper) loadRepoHandles(ctx context.Context, workspaceRoot, query string) ([]string, error) {
	query = strings.TrimSpace(query)
	if query == "" {
		return nil, nil
	}
	store, err := repoindex.Open(ctx, b.cfg.AppConfig.Storage.Root, workspaceRoot)
	if err != nil {
		return nil, nil
	}
	defer func() { _ = store.Close() }()
	output, err := repoquery.NewQueryService(repoindex.NewQueryEngine(store)).SearchWithProjection(ctx, repoquery.SearchRequest{
		Query: query,
		Limit: b.cfg.RepoHandleLimit,
	})
	if err != nil {
		return nil, nil
	}
	out := make([]string, 0, len(output.Anchors))
	for _, anchor := range output.Anchors {
		if strings.TrimSpace(anchor.Path) != "" {
			out = append(out, "path:"+filepath.ToSlash(anchor.Path))
		}
	}
	if len(out) == 0 {
		for _, node := range output.Nodes {
			if strings.TrimSpace(node.ID) != "" {
				out = append(out, "repo:"+node.ID)
			}
		}
	}
	return uniqueStrings(out), nil
}

func (b *Bootstrapper) loadVaultHandles(ctx context.Context, query string) ([]string, error) {
	query = strings.TrimSpace(query)
	vaultPath := firstNonEmpty(
		strings.TrimSpace(b.cfg.VaultPath),
		strings.TrimSpace(os.Getenv("FOXCTL_RLM_VAULT_PATH")),
		strings.TrimSpace(os.Getenv("FOXCTL_CONTEXTWIKI_VAULT_PATH")),
		strings.TrimSpace(os.Getenv("FOXCTL_OBSIDIAN_VAULT_PATH")),
	)
	if vaultPath == "" || query == "" {
		return nil, nil
	}
	index, err := obsidianindex.Open(ctx, b.cfg.AppConfig.Storage.Root, vaultPath)
	if err != nil {
		return nil, nil
	}
	defer func() { _ = index.Close() }()
	hits, err := index.SearchNotes(ctx, query, b.cfg.VaultHandleLimit)
	if err != nil {
		return nil, nil
	}
	out := make([]string, 0, len(hits))
	for _, hit := range hits {
		if strings.TrimSpace(hit.Path) != "" {
			out = append(out, "note:"+filepath.ToSlash(hit.Path))
		}
	}
	return uniqueStrings(out), nil
}

func readJSONFile(path string) (map[string]any, error) {
	if strings.TrimSpace(path) == "" {
		return nil, nil
	}
	body, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, err
	}
	if len(body) == 0 {
		return nil, nil
	}
	var out map[string]any
	if err := json.Unmarshal(body, &out); err != nil {
		return nil, err
	}
	return out, nil
}

func latestHandoff(dir string) (map[string]any, []string, error) {
	if strings.TrimSpace(dir) == "" {
		return nil, nil, nil
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil, nil
		}
		return nil, nil, err
	}
	sort.Slice(entries, func(i, j int) bool { return entries[i].Name() > entries[j].Name() })
	for _, entry := range entries {
		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".json") {
			continue
		}
		path := filepath.Join(dir, entry.Name())
		body, err := os.ReadFile(path)
		if err != nil {
			return nil, nil, err
		}
		var handoff contextplane.Handoff
		if err := json.Unmarshal(body, &handoff); err != nil {
			return nil, nil, err
		}
		payload := map[string]any{
			"path":          path,
			"task_id":       handoff.TaskID,
			"phase":         handoff.Phase,
			"outcome":       handoff.Outcome,
			"summary":       handoff.Summary,
			"created_at":    handoff.CreatedAt,
			"ref":           "note:handoff:" + entry.Name(),
			"evidence_refs": handoff.EvidenceRefs,
			"file_refs":     handoff.FileRefs,
		}
		refs := make([]string, 0, len(handoff.EvidenceRefs))
		for _, ref := range handoff.EvidenceRefs {
			if s := contextengine.FormatEvidenceRef(ref); s != "" {
				refs = append(refs, s)
			} else {
				refs = append(refs, ref.Ref)
			}
		}
		return payload, refs, nil
	}
	return nil, nil, nil
}

func topOfMindRefs(top map[string]any) []string {
	if top == nil {
		return nil
	}
	raw, ok := top["relevant_refs"].([]any)
	if !ok {
		return nil
	}
	out := make([]string, 0, len(raw))
	for _, item := range raw {
		if text := strings.TrimSpace(fmt.Sprint(item)); text != "" {
			out = append(out, text)
		}
	}
	return out
}

func loadCompanionHandles(ctx context.Context, db *sql.DB, limit int) ([]string, []string, error) {
	if db == nil || limit <= 0 {
		return nil, nil, nil
	}
	rows, err := db.QueryContext(ctx, `
		SELECT conversation_id, MAX(created_at) AS latest
		FROM companion_turns
		GROUP BY conversation_id
		ORDER BY latest DESC
		LIMIT ?`, limit)
	if err != nil {
		return nil, nil, nil
	}
	defer rows.Close()
	threadIDs := make([]string, 0, limit)
	sceneHandles := make([]string, 0, limit*2)
	for rows.Next() {
		var conversationID string
		var latest string
		if err := rows.Scan(&conversationID, &latest); err != nil {
			return nil, nil, err
		}
		conversationID = strings.TrimSpace(conversationID)
		if conversationID == "" {
			continue
		}
		threadIDs = append(threadIDs, conversationID)
		sceneHandles = append(sceneHandles, "conversation:"+conversationID)
		episodes, err := loadEpisodeHandles(ctx, db, conversationID, 2)
		if err == nil {
			sceneHandles = append(sceneHandles, episodes...)
		}
	}
	if err := rows.Err(); err != nil {
		return nil, nil, err
	}
	return uniqueStrings(threadIDs), uniqueStrings(sceneHandles), nil
}

func loadEpisodeHandles(ctx context.Context, db *sql.DB, conversationID string, limit int) ([]string, error) {
	rows, err := db.QueryContext(ctx, `
		SELECT id
		FROM companion_soft_episodes
		WHERE conversation_id = ?
		ORDER BY end_event_id DESC
		LIMIT ?`, conversationID, limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := make([]string, 0, limit)
	for rows.Next() {
		var id int64
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		out = append(out, fmt.Sprintf("episode:%d", id))
	}
	return out, rows.Err()
}

func (b *Bootstrapper) loadTrajectoryHandles(ctx context.Context, workspaceRoot string) ([]string, error) {
	if strings.TrimSpace(b.cfg.AppConfig.Storage.Root) == "" || strings.TrimSpace(workspaceRoot) == "" {
		return nil, nil
	}
	store, err := trajectory.Open(ctx, b.cfg.AppConfig.Storage.Root)
	if err != nil {
		return nil, nil
	}
	defer func() { _ = store.Close() }()
	trajs, err := store.ListTrajectories(ctx, trajectory.ListFilter{
		WorkspaceID: ws.ID(workspaceRoot),
		Limit:       b.cfg.ArtifactLimit,
	})
	if err != nil {
		return nil, nil
	}
	out := make([]string, 0, len(trajs)*2)
	for _, traj := range trajs {
		if strings.TrimSpace(traj.ID) != "" {
			out = append(out, "trajectory:"+traj.ID)
		}
		if strings.TrimSpace(traj.ArtifactDigest) != "" {
			out = append(out, "artifact:"+traj.ArtifactDigest)
		}
	}
	return uniqueStrings(out), nil
}

func uniqueStrings(values []string) []string {
	if len(values) == 0 {
		return nil
	}
	seen := make(map[string]struct{}, len(values))
	out := make([]string, 0, len(values))
	for _, value := range values {
		value = strings.TrimSpace(value)
		if value == "" {
			continue
		}
		if _, ok := seen[value]; ok {
			continue
		}
		seen[value] = struct{}{}
		out = append(out, value)
	}
	return out
}

func firstNonEmpty(values ...string) string {
	for _, value := range values {
		value = strings.TrimSpace(value)
		if value != "" {
			return value
		}
	}
	return ""
}

package contextengine

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"sync"
	"time"

	"github.com/joshka0/foxctl/internal/context/contextengine"
	"github.com/joshka0/foxctl/internal/storage/dbutil"
)

// Clock provides the current time. Inject for deterministic tests.
type Clock interface {
	Now() time.Time
}

// RealClock returns the actual system time.
type RealClock struct{}

func (RealClock) Now() time.Time { return time.Now().UTC() }

// EventFilter is an alias for the domain-level filter type.
type EventFilter = contextengine.EventFilter

// ClaimFilter is an alias for the domain-level filter type.
type ClaimFilter = contextengine.ClaimFilter

// StalenessFilter is an alias for the domain-level filter type.
type StalenessFilter = contextengine.StalenessFilter

// ImpactFilter is an alias for the domain-level filter type.
type ImpactFilter = contextengine.ImpactFilter

// ProjectionFilter is an alias for the domain-level filter type.
type ProjectionFilter = contextengine.ProjectionFilter

// RetrievalEpisodeFilter is an alias for the domain-level filter type.
type RetrievalEpisodeFilter = contextengine.RetrievalEpisodeFilter

// RetrievalFeedbackFilter is an alias for the domain-level filter type.
type RetrievalFeedbackFilter = contextengine.RetrievalFeedbackFilter

// Store defines the abstract persistence interface for the context engine.
type Store interface {
	// Close releases all resources. Safe to call multiple times.
	Close() error

	// Events (append-only).
	AppendEvent(ctx context.Context, event contextengine.ContextEvent) (contextengine.ContextEvent, error)
	ListEvents(ctx context.Context, filter EventFilter) ([]contextengine.ContextEvent, error)

	// Evidence packs.
	PutEvidencePack(ctx context.Context, pack contextengine.EvidencePack) (contextengine.EvidencePack, error)
	GetEvidencePack(ctx context.Context, id string) (contextengine.EvidencePack, error)

	// Evidence nodes.
	PutEvidenceNode(ctx context.Context, node contextengine.EvidenceNode) (contextengine.EvidenceNode, error)
	GetEvidenceNode(ctx context.Context, id string) (contextengine.EvidenceNode, error)
	ListEvidenceNodes(ctx context.Context, workspaceID string, ref contextengine.EvidenceRef, limit int) ([]contextengine.EvidenceNode, error)

	// Memory claims.
	UpsertClaim(ctx context.Context, claim contextengine.MemoryClaim) (contextengine.MemoryClaim, error)
	GetClaim(ctx context.Context, id string) (contextengine.MemoryClaim, error)
	ListClaims(ctx context.Context, filter ClaimFilter) ([]contextengine.MemoryClaim, error)

	// Impact edges.
	PutImpactEdge(ctx context.Context, edge contextengine.ImpactEdge) (contextengine.ImpactEdge, error)
	ListImpactEdges(ctx context.Context, filter ImpactFilter) ([]contextengine.ImpactEdge, error)
	// ReverseImpact returns all edges pointing to the target ref.
	ReverseImpact(ctx context.Context, workspaceID string, target contextengine.EvidenceRef) ([]contextengine.ImpactEdge, error)

	// Staleness markers.
	UpsertStaleness(ctx context.Context, marker contextengine.StalenessMarker) (contextengine.StalenessMarker, error)
	GetStaleness(ctx context.Context, id string) (contextengine.StalenessMarker, error)
	ListStaleness(ctx context.Context, filter StalenessFilter) ([]contextengine.StalenessMarker, error)

	// Projections.
	PutProjection(ctx context.Context, id, workspaceID, projectionType string, version int, taskID string, generatedFromEvents []string, payload any, generatedAt, expiresAt time.Time) error
	GetProjection(ctx context.Context, workspaceID, id string) (projectionType string, version int, taskID string, generatedFromEvents []string, payload json.RawMessage, generatedAt, expiresAt time.Time, err error)
	ListProjections(ctx context.Context, filter ProjectionFilter) ([]ProjectionRow, error)

	// Retrieval episodes (append-only).
	RecordRetrievalEpisode(ctx context.Context, episode contextengine.RetrievalEpisode) (contextengine.RetrievalEpisode, error)
	GetRetrievalEpisode(ctx context.Context, id string) (contextengine.RetrievalEpisode, error)
	ListRetrievalEpisodes(ctx context.Context, filter RetrievalEpisodeFilter) ([]contextengine.RetrievalEpisode, error)

	// Retrieval feedback (append-only).
	RecordRetrievalFeedback(ctx context.Context, feedback contextengine.RetrievalFeedback) (contextengine.RetrievalFeedback, error)
	GetRetrievalFeedback(ctx context.Context, id string) (contextengine.RetrievalFeedback, error)
	ListRetrievalFeedback(ctx context.Context, filter RetrievalFeedbackFilter) ([]contextengine.RetrievalFeedback, error)

	// Index verification (for testing).
	ExplainQueryPlan(ctx context.Context, query string, args ...any) (string, error)
}

// ProjectionRow is an alias for the domain-level type.
type ProjectionRow = contextengine.ProjectionRow

// sqliteStore implements Store using SQLite.
type sqliteStore struct {
	db    *sql.DB
	close func() error
	clock Clock
	cas   CASBackend
	// writeMu serializes write paths in-process. SQLite WAL mode allows
	// concurrent readers but only one writer; concurrent writers from lane
	// goroutines (e.g. retrieve_mixed) hit SQLITE_BUSY before busy_timeout
	// helps. Holding this mutex around every write keeps writers serialized
	// in-process so the SQLite lock is never contended.
	writeMu sync.Mutex
}

// CASBackend stores and retrieves large payloads outside the database.
type CASBackend interface {
	Put(ctx context.Context, data []byte) (digest string, err error)
	Get(ctx context.Context, digest string) ([]byte, error)
}

// Open initializes a new SQLite-backed Store.
func Open(ctx context.Context, root string, opts ...Option) (Store, error) {
	o := defaultOptions()
	for _, opt := range opts {
		opt(o)
	}

	db, closeFn, err := dbutil.OpenStoreDB(ctx, root, "CONTEXTENGINE", "contextengine.db", Migrate)
	if err != nil {
		return nil, fmt.Errorf("contextengine: open db: %w", err)
	}

	return &sqliteStore{db: db, close: closeFn, clock: o.clock, cas: o.cas}, nil
}

// OpenDB creates a Store from an existing *sql.DB (for testing).
func OpenDB(db *sql.DB, clock Clock, cas CASBackend) (Store, error) {
	return &sqliteStore{db: db, close: func() error { return nil }, clock: clock, cas: cas}, nil
}

// Option configures Store behavior.
type Option func(*options)

type options struct {
	clock Clock
	cas   CASBackend
}

func defaultOptions() *options {
	return &options{
		clock: RealClock{},
		cas:   nil, // no CAS by default
	}
}

// WithClock sets the clock for deterministic timestamps.
func WithClock(c Clock) Option {
	return func(o *options) { o.clock = c }
}

// WithCAS sets the CAS backend for large payloads.
func WithCAS(c CASBackend) Option {
	return func(o *options) { o.cas = c }
}

func (s *sqliteStore) Close() error {
	if s == nil || s.close == nil {
		return nil
	}
	return s.close()
}

// now returns the current time from the injected clock.
func (s *sqliteStore) now() time.Time {
	return s.clock.Now().UTC()
}

func decodeEvidenceRefs(column, raw string) ([]contextengine.EvidenceRef, error) {
	var refs []contextengine.EvidenceRef
	if err := json.Unmarshal([]byte(raw), &refs); err != nil {
		return nil, fmt.Errorf("decode %s: %w", column, err)
	}
	return refs, nil
}

func decodeStringSlice(column, raw string) ([]string, error) {
	var values []string
	if err := json.Unmarshal([]byte(raw), &values); err != nil {
		return nil, fmt.Errorf("decode %s: %w", column, err)
	}
	return values, nil
}

func decodeMetadata(column, raw string) (map[string]any, error) {
	var metadata map[string]any
	if err := json.Unmarshal([]byte(raw), &metadata); err != nil {
		return nil, fmt.Errorf("decode %s: %w", column, err)
	}
	return metadata, nil
}

func decodeTime(column, raw string) (time.Time, error) {
	if raw == "" {
		return time.Time{}, nil
	}
	t, err := time.Parse(time.RFC3339Nano, raw)
	if err == nil {
		return t, nil
	}
	if t, fallbackErr := time.Parse(time.RFC3339, raw); fallbackErr == nil {
		return t, nil
	}
	return time.Time{}, fmt.Errorf("decode %s: %w", column, err)
}

// --- Events (append-only) ---

func (s *sqliteStore) AppendEvent(ctx context.Context, event contextengine.ContextEvent) (contextengine.ContextEvent, error) {
	s.writeMu.Lock()
	defer s.writeMu.Unlock()
	if event.CreatedAt.IsZero() {
		event.CreatedAt = s.now()
	}
	if err := event.Validate(); err != nil {
		return contextengine.ContextEvent{}, fmt.Errorf("contextengine: append event: %w", err)
	}

	refsJSON, err := json.Marshal(event.Refs)
	if err != nil {
		return contextengine.ContextEvent{}, fmt.Errorf("contextengine: marshal refs: %w", err)
	}
	dataJSON, err := json.Marshal(event.Data)
	if err != nil {
		return contextengine.ContextEvent{}, fmt.Errorf("contextengine: marshal data: %w", err)
	}

	_, err = s.db.ExecContext(ctx, `
		INSERT INTO context_events (id, workspace_id, kind, source, task_id, session_id, refs, data, created_at)
		VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
		event.ID, event.WorkspaceID, string(event.Kind), event.Source,
		event.TaskID, event.SessionID, string(refsJSON), string(dataJSON),
		event.CreatedAt.UTC().Format(time.RFC3339Nano))
	if err != nil {
		return contextengine.ContextEvent{}, fmt.Errorf("contextengine: append event: %w", err)
	}
	return event, nil
}

func (s *sqliteStore) ListEvents(ctx context.Context, filter EventFilter) ([]contextengine.ContextEvent, error) {
	query := `SELECT id, workspace_id, kind, source, task_id, session_id, refs, data, created_at
		FROM context_events WHERE 1=1`
	var args []any

	if filter.WorkspaceID != "" {
		query += " AND workspace_id = ?"
		args = append(args, filter.WorkspaceID)
	}
	if filter.ID != "" {
		query += " AND id = ?"
		args = append(args, filter.ID)
	}
	if filter.Kind != "" {
		query += " AND kind = ?"
		args = append(args, string(filter.Kind))
	}
	if filter.TaskID != "" {
		query += " AND task_id = ?"
		args = append(args, filter.TaskID)
	}
	if filter.SessionID != "" {
		query += " AND session_id = ?"
		args = append(args, filter.SessionID)
	}

	query += " ORDER BY created_at DESC"

	if filter.Limit > 0 {
		query += " LIMIT ?"
		args = append(args, filter.Limit)
	}
	if filter.Offset > 0 {
		query += " OFFSET ?"
		args = append(args, filter.Offset)
	}

	rows, err := s.db.QueryContext(ctx, query, args...)
	if err != nil {
		return nil, fmt.Errorf("contextengine: list events: %w", err)
	}
	defer rows.Close()

	var events []contextengine.ContextEvent
	for rows.Next() {
		var e contextengine.ContextEvent
		var kind, refsJSON, dataJSON, createdAt string
		if err := rows.Scan(&e.ID, &e.WorkspaceID, &kind, &e.Source, &e.TaskID, &e.SessionID, &refsJSON, &dataJSON, &createdAt); err != nil {
			return nil, fmt.Errorf("contextengine: scan event: %w", err)
		}
		e.Kind = contextengine.ContextEventKind(kind)
		if err := json.Unmarshal([]byte(refsJSON), &e.Refs); err != nil {
			return nil, fmt.Errorf("contextengine: unmarshal refs: %w", err)
		}
		if err := json.Unmarshal([]byte(dataJSON), &e.Data); err != nil {
			return nil, fmt.Errorf("contextengine: unmarshal data: %w", err)
		}
		e.CreatedAt, err = decodeTime("created_at", createdAt)
		if err != nil {
			return nil, fmt.Errorf("contextengine: scan event: %w", err)
		}
		if err := e.Validate(); err != nil {
			return nil, fmt.Errorf("contextengine: scan event: %w", err)
		}
		events = append(events, e)
	}
	return events, rows.Err()
}

// --- Evidence Packs ---

const casThreshold = 64 * 1024 // 64KB

func (s *sqliteStore) PutEvidencePack(ctx context.Context, pack contextengine.EvidencePack) (contextengine.EvidencePack, error) {
	s.writeMu.Lock()
	defer s.writeMu.Unlock()
	if err := pack.Validate(); err != nil {
		return contextengine.EvidencePack{}, fmt.Errorf("contextengine: put pack: %w", err)
	}

	nodesJSON, err := json.Marshal(pack.Nodes)
	if err != nil {
		return contextengine.EvidencePack{}, fmt.Errorf("contextengine: marshal nodes: %w", err)
	}
	telemetryJSON, err := json.Marshal(pack.Telemetry)
	if err != nil {
		return contextengine.EvidencePack{}, fmt.Errorf("contextengine: marshal telemetry: %w", err)
	}
	metadataJSON, err := json.Marshal(pack.Metadata)
	if err != nil {
		return contextengine.EvidencePack{}, fmt.Errorf("contextengine: marshal metadata: %w", err)
	}

	var casDigest string
	if s.cas != nil && len(nodesJSON) > casThreshold {
		digest, cerr := s.cas.Put(ctx, nodesJSON)
		if cerr != nil {
			return contextengine.EvidencePack{}, fmt.Errorf("contextengine: cas put: %w", cerr)
		}
		casDigest = digest
		nodesJSON = []byte("[]") // clear inline nodes
	}

	createdAt := s.now()
	_, err = s.db.ExecContext(ctx, `
		INSERT INTO evidence_packs (id, workspace_id, query, lane, nodes, telemetry, metadata, cas_digest, created_at)
		VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
		ON CONFLICT(id) DO UPDATE SET
			query = excluded.query, lane = excluded.lane, nodes = excluded.nodes,
			telemetry = excluded.telemetry, metadata = excluded.metadata,
			cas_digest = excluded.cas_digest`,
		pack.ID, pack.WorkspaceID, pack.Query, string(pack.Lane),
		string(nodesJSON), string(telemetryJSON), string(metadataJSON),
		casDigest, createdAt.UTC().Format(time.RFC3339Nano))
	if err != nil {
		return contextengine.EvidencePack{}, fmt.Errorf("contextengine: put pack: %w", err)
	}
	return pack, nil
}

func (s *sqliteStore) GetEvidencePack(ctx context.Context, id string) (contextengine.EvidencePack, error) {
	row := s.db.QueryRowContext(ctx, `
		SELECT id, workspace_id, query, lane, nodes, telemetry, metadata, cas_digest, created_at
		FROM evidence_packs WHERE id = ?`, id)

	var pack contextengine.EvidencePack
	var lane, nodesJSON, telemetryJSON, metadataJSON, casDigest, createdAt string
	if err := row.Scan(&pack.ID, &pack.WorkspaceID, &pack.Query, &lane,
		&nodesJSON, &telemetryJSON, &metadataJSON, &casDigest, &createdAt); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return contextengine.EvidencePack{}, ErrNotFound
		}
		return contextengine.EvidencePack{}, fmt.Errorf("contextengine: get pack: %w", err)
	}
	pack.Lane = contextengine.EvidenceLane(lane)

	if casDigest != "" && s.cas != nil {
		data, err := s.cas.Get(ctx, casDigest)
		if err != nil {
			return contextengine.EvidencePack{}, fmt.Errorf("contextengine: cas get: %w", err)
		}
		if err := json.Unmarshal(data, &pack.Nodes); err != nil {
			return contextengine.EvidencePack{}, fmt.Errorf("contextengine: unmarshal cas nodes: %w", err)
		}
	} else {
		if err := json.Unmarshal([]byte(nodesJSON), &pack.Nodes); err != nil {
			return contextengine.EvidencePack{}, fmt.Errorf("contextengine: unmarshal nodes: %w", err)
		}
	}

	if err := json.Unmarshal([]byte(telemetryJSON), &pack.Telemetry); err != nil {
		return contextengine.EvidencePack{}, fmt.Errorf("contextengine: unmarshal telemetry: %w", err)
	}
	if err := json.Unmarshal([]byte(metadataJSON), &pack.Metadata); err != nil {
		return contextengine.EvidencePack{}, fmt.Errorf("contextengine: unmarshal metadata: %w", err)
	}
	if err := pack.Validate(); err != nil {
		return contextengine.EvidencePack{}, fmt.Errorf("contextengine: get pack: %w", err)
	}
	// Pack doesn't have CreatedAt in the domain type; skip returning it
	return pack, nil
}

// --- Evidence Nodes ---

func (s *sqliteStore) PutEvidenceNode(ctx context.Context, node contextengine.EvidenceNode) (contextengine.EvidenceNode, error) {
	s.writeMu.Lock()
	defer s.writeMu.Unlock()
	if err := node.Validate(); err != nil {
		return contextengine.EvidenceNode{}, fmt.Errorf("contextengine: put node: %w", err)
	}

	metadataJSON, err := json.Marshal(node.Metadata)
	if err != nil {
		return contextengine.EvidenceNode{}, fmt.Errorf("contextengine: marshal metadata: %w", err)
	}

	var casDigest string
	statement := node.Statement
	if s.cas != nil && len(node.Statement) > casThreshold {
		digest, cerr := s.cas.Put(ctx, []byte(node.Statement))
		if cerr != nil {
			return contextengine.EvidenceNode{}, fmt.Errorf("contextengine: cas put: %w", cerr)
		}
		casDigest = digest
		statement = ""
	}

	_, err = s.db.ExecContext(ctx, `
		INSERT INTO evidence_nodes (id, workspace_id, node_type, ref_type, ref_value, statement,
			confidence, grounding, count, first_seen, last_seen, metadata, cas_digest)
		VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
		ON CONFLICT(id) DO UPDATE SET
			node_type = excluded.node_type, statement = excluded.statement,
			confidence = excluded.confidence, grounding = excluded.grounding,
			count = excluded.count, last_seen = excluded.last_seen,
			metadata = excluded.metadata, cas_digest = excluded.cas_digest`,
		node.ID, node.WorkspaceID, string(node.NodeType),
		string(node.Ref.Type), node.Ref.Ref, statement,
		node.Confidence, string(node.Grounding), node.Count,
		node.FirstSeen.UTC().Format(time.RFC3339Nano),
		node.LastSeen.UTC().Format(time.RFC3339Nano),
		string(metadataJSON), casDigest)
	if err != nil {
		return contextengine.EvidenceNode{}, fmt.Errorf("contextengine: put node: %w", err)
	}
	return node, nil
}

func (s *sqliteStore) GetEvidenceNode(ctx context.Context, id string) (contextengine.EvidenceNode, error) {
	row := s.db.QueryRowContext(ctx, `
		SELECT id, workspace_id, node_type, ref_type, ref_value, statement,
			confidence, grounding, count, first_seen, last_seen, metadata, cas_digest
		FROM evidence_nodes WHERE id = ?`, id)

	return s.scanNode(row)
}

func (s *sqliteStore) ListEvidenceNodes(ctx context.Context, workspaceID string, ref contextengine.EvidenceRef, limit int) ([]contextengine.EvidenceNode, error) {
	if limit <= 0 {
		limit = 50
	}
	rows, err := s.db.QueryContext(ctx, `
		SELECT id, workspace_id, node_type, ref_type, ref_value, statement,
			confidence, grounding, count, first_seen, last_seen, metadata, cas_digest
		FROM evidence_nodes
		WHERE workspace_id = ? AND ref_type = ? AND ref_value = ?
		ORDER BY last_seen DESC LIMIT ?`,
		workspaceID, string(ref.Type), ref.Ref, limit)
	if err != nil {
		return nil, fmt.Errorf("contextengine: list nodes: %w", err)
	}
	defer rows.Close()

	var nodes []contextengine.EvidenceNode
	for rows.Next() {
		var node contextengine.EvidenceNode
		var nodeType, refType, refValue, statement, grounding, firstSeen, lastSeen, metadataJSON, casDigest string
		if err := rows.Scan(&node.ID, &node.WorkspaceID, &nodeType, &refType, &refValue, &statement,
			&node.Confidence, &grounding, &node.Count, &firstSeen, &lastSeen, &metadataJSON, &casDigest); err != nil {
			return nil, fmt.Errorf("contextengine: scan node: %w", err)
		}
		node.NodeType = contextengine.EvidenceNodeType(nodeType)
		node.Ref = contextengine.EvidenceRef{Type: contextengine.RefType(refType), Ref: refValue}
		node.Grounding = contextengine.Grounding(grounding)
		node.FirstSeen, err = decodeTime("first_seen", firstSeen)
		if err != nil {
			return nil, fmt.Errorf("contextengine: scan node: %w", err)
		}
		node.LastSeen, err = decodeTime("last_seen", lastSeen)
		if err != nil {
			return nil, fmt.Errorf("contextengine: scan node: %w", err)
		}
		metadata, err := decodeMetadata("metadata", metadataJSON)
		if err != nil {
			return nil, fmt.Errorf("contextengine: scan node: %w", err)
		}
		node.Metadata = metadata

		if casDigest != "" && s.cas != nil {
			data, cerr := s.cas.Get(ctx, casDigest)
			if cerr == nil {
				node.Statement = string(data)
			}
		} else {
			node.Statement = statement
		}
		if err := node.Validate(); err != nil {
			return nil, fmt.Errorf("contextengine: scan node: %w", err)
		}
		nodes = append(nodes, node)
	}
	return nodes, rows.Err()
}

func (s *sqliteStore) scanNode(row *sql.Row) (contextengine.EvidenceNode, error) {
	var node contextengine.EvidenceNode
	var nodeType, refType, refValue, statement, grounding, firstSeen, lastSeen, metadataJSON, casDigest string
	if err := row.Scan(&node.ID, &node.WorkspaceID, &nodeType, &refType, &refValue, &statement,
		&node.Confidence, &grounding, &node.Count, &firstSeen, &lastSeen, &metadataJSON, &casDigest); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return contextengine.EvidenceNode{}, ErrNotFound
		}
		return contextengine.EvidenceNode{}, fmt.Errorf("contextengine: scan node: %w", err)
	}
	node.NodeType = contextengine.EvidenceNodeType(nodeType)
	node.Ref = contextengine.EvidenceRef{Type: contextengine.RefType(refType), Ref: refValue}
	node.Grounding = contextengine.Grounding(grounding)
	var err error
	node.FirstSeen, err = decodeTime("first_seen", firstSeen)
	if err != nil {
		return contextengine.EvidenceNode{}, fmt.Errorf("contextengine: scan node: %w", err)
	}
	node.LastSeen, err = decodeTime("last_seen", lastSeen)
	if err != nil {
		return contextengine.EvidenceNode{}, fmt.Errorf("contextengine: scan node: %w", err)
	}
	metadata, err := decodeMetadata("metadata", metadataJSON)
	if err != nil {
		return contextengine.EvidenceNode{}, fmt.Errorf("contextengine: scan node: %w", err)
	}
	node.Metadata = metadata

	if casDigest != "" && s.cas != nil {
		data, err := s.cas.Get(context.Background(), casDigest)
		if err == nil {
			node.Statement = string(data)
		}
	} else {
		node.Statement = statement
	}
	if err := node.Validate(); err != nil {
		return contextengine.EvidenceNode{}, fmt.Errorf("contextengine: scan node: %w", err)
	}
	return node, nil
}

