	episodeID := fmt.Sprintf("episode-answer-%s", deterministicAnswerEpisodeID(task, accepted))
	feedback := contextengine.RetrievalFeedback{
		ID:          fmt.Sprintf("feedback-%s", episodeID),
		WorkspaceID: task.WorkspaceID,
		EpisodeID:   episodeID,
		Kind:        contextengine.RetrievalFeedbackKindAnswerAccepted,
		Query:       task.Prompt,
		UsedRefs:    usedRefs,
		CreatedAt:   time.Now().UTC(),
	}
	if _, err := contextengine.RecordRetrievalFeedbackWithEffects(ctx, r.FeedbackStore, feedback); err != nil {
		// Best-effort: never fail the answer path because feedback recording failed.
	}
}

func parseAcceptedLedgerEvidenceRefs(values []string) []contextengine.EvidenceRef {
	out := make([]contextengine.EvidenceRef, 0, len(values))
	seen := make(map[string]struct{}, len(values))
	for _, value := range values {
		ref, ok := parseAcceptedLedgerEvidenceRef(value)
		if !ok {
			continue
		}
		key := contextengine.FormatEvidenceRef(ref)
		if _, dup := seen[key]; dup {
			continue
		}
		seen[key] = struct{}{}
		out = append(out, ref)
	}
	return out
}

func parseAcceptedLedgerEvidenceRef(value string) (contextengine.EvidenceRef, bool) {
	value = strings.TrimSpace(value)
	if value == "" {
		return contextengine.EvidenceRef{}, false
	}
	// Accepted ledger rows may carry a trailing snippet:
	//   "path:internal/rlm/types.go: The runner should cite..."
	if idx := strings.Index(value, ": "); idx >= 0 {
		value = strings.TrimSpace(value[:idx])
	}
	parts := strings.SplitN(value, ":", 2)
	if len(parts) != 2 {
		return contextengine.EvidenceRef{}, false
	}
	refType := strings.TrimSpace(parts[0])
	refValue := strings.TrimSpace(parts[1])
	if refType == "" || refValue == "" {
		return contextengine.EvidenceRef{}, false
	}
	return contextengine.EvidenceRef{
		Type: contextengine.RefType(refType),
		Ref:  refValue,
	}, true
}

func deterministicAnswerEpisodeID(task Task, acceptedRefs []string) string {
	h := sha256.New()
	if task.RunID != "" {
		h.Write([]byte(task.RunID))
	} else {
		h.Write([]byte(task.Prompt))
	}
	sorted := append([]string(nil), acceptedRefs...)
	sort.Strings(sorted)
	for _, ref := range sorted {
		h.Write([]byte(ref))
	}
	return hex.EncodeToString(h.Sum(nil))[:16]
}
