I'll take **Slice 4 — REQUIRED_DATA-style runner-enforced fallback re-query**.

Good news: `evidence_ledger` already computes the fallback payload we need. Its output contains:

- `needs_fallback` bool
- `answer_outline.missing_slots`
- `fallback_gather_calls` — ready-to-run `gather_context` calls generated by `contextQueryFallbackProbes`

So Slice 4 can be a **deterministic, bounded runner retry** rather than a prompt-based one: when the deterministic ledger fallback reports missing required slots, run its `fallback_gather_calls`, merge the newly surfaced refs, and rebuild the ledger once.

## Design

Modify `tryDeterministicEvidenceLedgerPhase` in `internal/rlm/llm_runner.go`:

1. Run the ledger once (same as today).
2. If `needs_fallback == true` and `fallback_gather_calls` is non-empty, execute each call via `gather_context`.
3. Collect surfaced refs from the gather results and merge with the original refs.
4. Re-run `evidence_ledger` with the merged refs.
5. Use the repaired ledger if it is either `ready` or has strictly more accepted refs than the first attempt.

This is bounded: one repair pass per deterministic ledger fallback, with at most 3 fallback gather calls (the existing cap in `contextQueryFallbackProbes`).

## Patch

Replace `tryDeterministicEvidenceLedgerPhase` and add the helpers below.

```go
func (r LLMRunner) tryDeterministicEvidenceLedgerPhase(ctx context.Context, task Task, phase Phase, phaseResult Result, priorSurfacedEvidence []string) (Result, bool) {
	refs := deterministicEvidenceLedgerRefs(priorSurfacedEvidence, stringsFromAnySlice(phaseResult.Metadata["tool_surfaced_evidence_refs"]))
	if len(refs) == 0 {
		return Result{}, false
	}
	out, argsJSON, ok := r.runEvidenceLedgerTool(ctx, task, phase, refs)
	if !ok {
		return Result{}, false
	}
	if needsEvidenceLedgerFallback(out) {
		fallbackCalls := nestedMapSlice(out, "fallback_gather_calls")
		repairedRefs := r.runFallbackGatherCalls(ctx, task, phase, fallbackCalls)
		if len(repairedRefs) > 0 {
			combined := uniqueStringsRLM(append(refs, repairedRefs...))
			if newOut, newArgsJSON, newOK := r.runEvidenceLedgerTool(ctx, task, phase, combined); newOK {
				if !needsEvidenceLedgerFallback(newOut) || moreAcceptedRefs(newOut, out) {
					out = newOut
					argsJSON = newArgsJSON
				}
			}
		}
	}
	return r.buildDeterministicEvidenceLedgerResult(ctx, task, phase, out, argsJSON, refs)
}

func (r LLMRunner) runEvidenceLedgerTool(ctx context.Context, task Task, phase Phase, refs []string) (map[string]any, []byte, bool) {
	args := map[string]any{
		"query":              evidenceLedgerQueryFromTaskPrompt(task.Prompt),
		"refs":               refs,
		"max_refs":           len(refs),
		"max_tokens_per_ref": 1200,
	}
	argsJSON, err := json.Marshal(args)
	if err != nil {
		return nil, nil, false
	}
	out, err := newAllowlistedToolExecutor(r.Tools, []Tool{{Name: "evidence_ledger", ReadOnly: true}}).Execute(ctx, "evidence_ledger", argsJSON)
	if err != nil {
		return nil, nil, false
	}
	content, err := json.Marshal(out)
	if err != nil {
		return nil, nil, false
	}
	var parsed map[string]any
	if err := json.Unmarshal(content, &parsed); err != nil {
		return nil, nil, false
	}
	return parsed, argsJSON, true
}

func (r LLMRunner) runFallbackGatherCalls(ctx context.Context, task Task, phase Phase, fallbackCalls []any) []string {
	if len(fallbackCalls) == 0 {
		return nil
	}
	gatherExec := newAllowlistedToolExecutor(r.Tools, []Tool{{Name: "gather_context", ReadOnly: true}})
	var newRefs []string
	for i, raw := range fallbackCalls {
		call, ok := raw.(map[string]any)
		if !ok {
			continue
		}
		argsJSON, err := json.Marshal(call)
		if err != nil {
			continue
		}
		out, err := gatherExec.Execute(ctx, "gather_context", argsJSON)
		if err != nil {
			continue
		}
		content, err := json.Marshal(out)
		if err != nil {
			continue
		}
		callID := fmt.Sprintf("fallback-gather-%s-%d", phase.Name, i)
		calls := []engine.ToolCall{{
			ID:        callID,
			Name:      "gather_context",
			Arguments: argsJSON,
		}}
		results := []engine.ToolResult{{
			ToolCallID: callID,
			Content:    string(content),
		}}
		refs := collectSurfacedToolEvidenceRefs(calls, results)
		newRefs = uniqueStringsRLM(append(newRefs, refs...))
	}
	return newRefs
}

func (r LLMRunner) buildDeterministicEvidenceLedgerResult(ctx context.Context, task Task, phase Phase, out map[string]any, argsJSON []byte, refs []string) (Result, bool) {
	content, err := json.Marshal(out)
	if err != nil {
		return Result{}, false
	}
	callID := "deterministic-" + phase.Name + "-evidence-ledger"
	calls := []engine.ToolCall{{
		ID:        callID,
		Name:      "evidence_ledger",
		Arguments: argsJSON,
	}}
	results := []engine.ToolResult{{
		ToolCallID: callID,
		Content:    string(content),
	}}
	surfacedEvidence := collectSurfacedToolEvidenceRefs(calls, results)
	acceptedLedgerEvidence := collectAcceptedLedgerEvidenceRows(calls, results)
	answer := deterministicEvidenceLedgerPhaseAnswer(out)
	return Result{
		Answer:         answer,
		RetrievedPaths: collectRetrievedPaths(results, task.WorkspaceRoot, answer),
		Subcalls:       1,
		Iterations:     1,
		Metadata: map[string]any{
			"stop_reason":                  engine.StopReasonEndTurn,
			"tool_calls":                   1,
			"tool_names":                   []string{"evidence_ledger"},
			"require_tool_use":             true,
			"tool_surfaced_evidence_refs":  surfacedEvidence,
			"answer_used_evidence_refs":    collectAnswerUsedEvidenceRefs(answer, surfacedEvidence),
			"accepted_ledger_evidence":     acceptedLedgerEvidence,
			"retrieved_paths":              collectRetrievedPaths(results, task.WorkspaceRoot, answer),
			"parent_input_tokens":          0,
			"parent_output_tokens":         0,
			"parent_total_tokens":          0,
			"parent_iteration_count":       0,
			"parent_tool_usage":            map[string]any{},
			"deterministic_tool_fallback":  "evidence_ledger",
			"deterministic_fallback_refs":  refs,
			"deterministic_fallback_phase": phase.Name,
		},
	}, true
}

func needsEvidenceLedgerFallback(out map[string]any) bool {
	if out == nil {
		return false
	}
	raw, ok := out["needs_fallback"]
	if !ok {
		return false
	}
	if b, ok := raw.(bool); ok {
		return b
	}
	if s, ok := raw.(string); ok {
		return strings.EqualFold(s, "true")
	}
	return false
}

func moreAcceptedRefs(a, b map[string]any) bool {
	aRefs := stringsFromAny(nestedMapValue(a, []string{"accepted_refs"}))
	bRefs := stringsFromAny(nestedMapValue(b, []string{"accepted_refs"}))
	return len(aRefs) > len(bRefs)
}

func nestedMapSlice(out map[string]any, key string) []any {
	if out == nil {
		return nil
	}
	raw, ok := out[key]
	if !ok {
		return nil
	}
	if s, ok := raw.([]any); ok {
		return s
	}
	return nil
}
```

## What this does in the smoke cases

- The first `evidence_ledger` pass may miss a required slot (e.g., the exact degree, the store location, the model kit item).
- The ledger already emits targeted fallback queries like `query + top evidence anchor`.
- The runner now executes those probes through `gather_context`, surfaces new refs, and rebuilds the ledger.
- If the repaired ledger covers the missing slot, the answer path proceeds with accepted evidence instead of hallucinating or refusing.

## Verification

```bash
go test ./internal/rlm ./internal/rlm/env ./internal/context/contextengine -count=1
go test ./cmd/foxctl/cmd -run 'TestEvalLongmem' -count=1
```

If you want, I can also add a focused unit test that feeds a fake `evidence_ledger` result with `needs_fallback=true` and asserts `runFallbackGatherCalls` is invoked.

package memoryrecall

import (
	"context"
	"fmt"
	"strings"

	"github.com/joshka0/foxctl/internal/intelligence/searchrank"
	"github.com/joshka0/foxctl/internal/storage"
)

const (
	DefaultMinSimilarity = 0.3

	MethodBM25   = "bm25"
	MethodVector = "vector"
	MethodHybrid = "hybrid"

	sourceVector  = searchrank.SourceID("vector")
	sourceLexical = searchrank.SourceID("lexical")

	// defaultStandardCandidateThreshold is the lifecycle gate for candidate
	// and stale memories in standard (point-fact) queries. It is intentionally
	// lower than the previous hardcoded 0.9, which suppressed legitimate
	// synonymy and paraphrase matches before they could reach evidence
	// verification.
	defaultStandardCandidateThreshold = 0.38
	// defaultDeepCandidateThreshold is the gate for deep (exploratory,
	// aggregation, categorical) queries where wider recall is preferred.
	defaultDeepCandidateThreshold = 0.28
)

// Store is the named-memory retrieval surface required for hybrid recall.
type Store interface {
	Search(ctx context.Context, workspace, query string, limit int) ([]storage.ScoredEntry, error)
	SearchSimilar(ctx context.Context, workspace string, embedding []float32, limit int) ([]storage.ScoredEntry, error)
}

type QueryRequest struct {
	Workspace      string
	Query          string
	QueryEmbedding []float32
	EmbeddingError error
	VectorContext  context.Context
	Limit          int
}

type QueryResponse struct {
	Entries []storage.ScoredEntry
	Method  string
	Hint    string
}

// Search runs the canonical named-memory recall flow: vector candidates and
// lexical candidates are fetched concurrently, then weighted fusion is applied
// when both sources are available. When vector search fails or times out,
// lexical results (already in flight) are used without waiting.
func Search(ctx context.Context, store Store, req QueryRequest) (QueryResponse, error) {
	if store == nil {
		return QueryResponse{Method: MethodBM25}, fmt.Errorf("memory recall store is nil")
	}
	if strings.TrimSpace(req.Query) == "" {
		return QueryResponse{Method: MethodBM25}, fmt.Errorf("memory recall query is empty")
	}

	limit := req.Limit
	if limit <= 0 {
		limit = 10
	}

	// If no embedding is available, skip straight to BM25.
	if len(req.QueryEmbedding) == 0 || req.EmbeddingError != nil {
		lexicalEntries, lexicalErr := store.Search(ctx, req.Workspace, req.Query, limit)
		if lexicalErr != nil {
			return QueryResponse{Method: MethodBM25}, lexicalErr
		}
		hint := ""
		if req.EmbeddingError != nil {
			hint = fmt.Sprintf("vector search failed: %v; using BM25", req.EmbeddingError)
		}
		return QueryResponse{Entries: lexicalEntries, Method: MethodBM25, Hint: hint}, nil
	}

	// Run vector and lexical concurrently.
	type vectorResult struct {
		entries []storage.ScoredEntry
		err     error
	}
	type lexicalResult struct {
		entries []storage.ScoredEntry
		err     error
	}

	vectorCh := make(chan vectorResult, 1)
	lexicalCh := make(chan lexicalResult, 1)

	go func() {
		entries, err := searchVector(ctx, store, req, limit)
		vectorCh <- vectorResult{entries: entries, err: err}
	}()
	go func() {
		entries, err := store.Search(ctx, req.Workspace, req.Query, limit)
		lexicalCh <- lexicalResult{entries: entries, err: err}
	}()

	vr := <-vectorCh
	lr := <-lexicalCh

	vectorEntries := vr.entries
	vectorErr := vr.err
	lexicalEntries := lr.entries
	lexicalErr := lr.err

	// Both failed.
	if vectorErr != nil && lexicalErr != nil {
		if ctx.Err() != nil {
			return QueryResponse{Method: MethodVector}, vectorErr
		}
		return QueryResponse{Method: MethodBM25}, lexicalErr
	}

	// Vector failed — use lexical.
	if vectorErr != nil {
		if len(lexicalEntries) == 0 {
			return QueryResponse{Method: MethodBM25}, lexicalErr
		}
		return QueryResponse{
			Entries: lexicalEntries,
			Method:  MethodBM25,
			Hint:    fmt.Sprintf("vector search failed: %v; using BM25", vectorErr),
		}, nil
	}

	// Lexical failed — use vector.
	if lexicalErr != nil {
		if len(vectorEntries) == 0 {
			return QueryResponse{Method: MethodVector}, lexicalErr
		}
		return QueryResponse{
			Entries: vectorEntries,
			Method:  MethodVector,
			Hint:    fmt.Sprintf("BM25 search failed: %v; using vector", lexicalErr),
		}, nil
	}

	// Both succeeded — fuse if both have entries.
	if len(vectorEntries) == 0 {
		return QueryResponse{
			Entries: lexicalEntries,
			Method:  MethodBM25,
			Hint:    "vector search returned no records; using BM25",
		}, nil
	}
	if len(lexicalEntries) == 0 {
		return QueryResponse{Entries: vectorEntries, Method: MethodVector}, nil
	}
	return QueryResponse{
		Entries: fuseResults(vectorEntries, lexicalEntries, limit),
		Method:  MethodHybrid,
	}, nil
}

func searchVector(ctx context.Context, store Store, req QueryRequest, limit int) ([]storage.ScoredEntry, error) {
	if req.EmbeddingError != nil {
		return nil, req.EmbeddingError
	}
	if len(req.QueryEmbedding) == 0 {
		return nil, fmt.Errorf("query embedding is empty")
	}
	vectorCtx := req.VectorContext
	if vectorCtx == nil {
		vectorCtx = ctx
	}
	return store.SearchSimilar(vectorCtx, req.Workspace, req.QueryEmbedding, limit)
}

// DefaultLifecycleAllows applies the named-memory recall default lifecycle
// gate. Explicit lifecycle filters live at the caller layer.
func DefaultLifecycleAllows(state string, score float64, query string) bool {
	return LifecycleAllowsThreshold(state, score, query, defaultStandardCandidateThreshold)
}

// LifecycleAllowsThreshold applies the named-memory recall lifecycle gate
// using the provided candidate threshold instead of the default standard
// threshold. Callers that classify queries as "deep" (exploratory,
// aggregation, categorical) should pass defaultDeepCandidateThreshold.
func LifecycleAllowsThreshold(state string, score float64, query string, candidateThreshold float64) bool {
	switch strings.TrimSpace(state) {
	case "", "active":
		return true
	case "candidate", "stale":
		if strings.TrimSpace(query) == "" {
			return false
		}
		return score >= candidateThreshold
	default:
		return false
	}
}

// QueryClassDeep returns true for queries that should use the deep-mode
// candidate threshold (wider recall). Deep queries include aggregations,
// broad categories, recommendations, and multi-session questions — patterns
// adapted from Quarq's search_mode heuristic but implemented as a pure
// string classifier without keyword heuristics on classification decisions.
// The classification is intentionally conservative: only queries that clearly
// ask for broad/exploratory recall are classified as deep.
func QueryClassDeep(query string) bool {
	q := strings.ToLower(strings.TrimSpace(query))
	if q == "" {
		return false
	}
	// Multi-clause questions (contain "and" joining two distinct question
	// clauses) are exploratory.
	clauseCount := strings.Count(q, "?")
	if clauseCount > 1 {
		return true
	}
	return false
}

// CandidateThresholdForQuery returns the appropriate candidate threshold
// for the given query.
func CandidateThresholdForQuery(query string) float64 {
	if QueryClassDeep(query) {
		return defaultDeepCandidateThreshold
	}
	return defaultStandardCandidateThreshold
}

// QuerySimilarityAllows applies the default named-memory query similarity gate.
func QuerySimilarityAllows(score float64, query string, minSimilarity float64) bool {
	if strings.TrimSpace(query) == "" {
		return true
	}
	if minSimilarity <= 0 {
		minSimilarity = DefaultMinSimilarity
	}
	return score >= minSimilarity
}

// NamedEntryText returns the default text surface for named-memory recall.
func NamedEntryText(entry storage.NamedEntry) string {
	base := firstNonEmpty(
		strings.TrimSpace(entry.AtomicText),
		strings.TrimSpace(entry.Summary),
		strings.TrimSpace(entry.Name),
	)
	tags := NamedEntryTags(entry)
	if len(tags) > 0 {
		base = strings.TrimSpace(base + " Tags: " + strings.Join(tags, ", "))
	}
	return base
}

// NamedEntryTags returns unique entity and keyword tags in stored order.
func NamedEntryTags(entry storage.NamedEntry) []string {
	seen := make(map[string]struct{})
	tags := make([]string, 0, len(entry.Entities)+len(entry.Keywords))
	for _, values := range [][]string{entry.Entities, entry.Keywords} {
		for _, value := range values {
			value = strings.TrimSpace(value)
			if value == "" {
				continue
			}
			key := strings.ToLower(value)
			if _, ok := seen[key]; ok {
				continue
			}
			seen[key] = struct{}{}
			tags = append(tags, value)
		}
	}
	return tags
}

func firstNonEmpty(values ...string) string {
	for _, value := range values {
		value = strings.TrimSpace(value)
		if value != "" {
			return value
		}
	}
	return ""
}

func fuseResults(vectorEntries, lexicalEntries []storage.ScoredEntry, limit int) []storage.ScoredEntry {
	sourceHits := map[searchrank.SourceID][]searchrank.SourceHit[storage.ScoredEntry]{
		sourceVector:  sourceHitsFromScoredEntries(sourceVector, vectorEntries),
		sourceLexical: sourceHitsFromScoredEntries(sourceLexical, lexicalEntries),
	}
	fused := searchrank.Fuse(sourceHits, searchrank.FuseOptions{
		Mode: searchrank.FuseModeWeighted,
		TopK: limit,
		RRFK: 60,
		SourceWeights: map[searchrank.SourceID]float64{
			sourceVector:  0.45,
			sourceLexical: 0.55,
		},
		MaxContributors: 2,
	})
	results := make([]storage.ScoredEntry, 0, len(fused))
	for _, hit := range fused {
		scored := hit.Document
		scored.Score = hit.Score
		results = append(results, scored)
	}
	return results
}

func sourceHitsFromScoredEntries(source searchrank.SourceID, entries []storage.ScoredEntry) []searchrank.SourceHit[storage.ScoredEntry] {
	hits := make([]searchrank.SourceHit[storage.ScoredEntry], 0, len(entries))
	for i, entry := range entries {
		id := strings.TrimSpace(entry.Entry.Name)
		if id == "" {
			id = strings.TrimSpace(entry.Entry.ID)
		}
		if id == "" {
			continue
		}
		hits = append(hits, searchrank.SourceHit[storage.ScoredEntry]{
			Source:   source,
			ID:       id,
			Document: entry,
			Score:    entry.Score,
			Rank:     i + 1,
		})
	}
	return hits
}

package env

import (
	"context"
	"strings"
	"time"

	"github.com/joshka0/foxctl/internal/context/contextengine"
	"github.com/joshka0/foxctl/internal/intelligence/indexing/semantic"
	"github.com/joshka0/foxctl/internal/intelligence/retrieval/memoryrecall"
	"github.com/joshka0/foxctl/internal/storage"
	memorystore "github.com/joshka0/foxctl/internal/storage/memory"
)

const namedMemoryRecallVectorSearchTimeout = 8 * time.Second

type namedMemoryGatherOptions struct {
	CoverageRepair       bool
	RequiredEvidence     []string
	CoverageRequirements []contextengine.CoverageRequirement
}

func (a *ReadOnlyAdapter) retrieveNamedMemory(ctx context.Context, cfg contextengine.LaneConfig, query string, limit int) (contextengine.EvidencePack, bool, error) {
	if strings.TrimSpace(query) == "" {
		return contextengine.EvidencePack{}, false, nil
	}
	if strings.TrimSpace(a.cfg.Storage.Root) == "" || strings.TrimSpace(a.workspaceRoot) == "" {
		return contextengine.EvidencePack{}, false, nil
	}

	memStore, err := memorystore.OpenWithConfig(ctx, a.cfg)
	if err != nil {
		return contextengine.EvidencePack{}, false, nil
	}
	defer func() { _ = memStore.Close() }()

	start := cfg.Clock()
	vectorCtx, cancelVectorSearch := namedMemoryRecallVectorContext(ctx)
	queryEmbedding, embeddingErr := a.embedNamedMemoryQuery(vectorCtx, memStore, cfg.WorkspaceID, query)
	if embeddingErr != nil && ctx.Err() != nil {
		cancelVectorSearch()
		return contextengine.EvidencePack{}, true, embeddingErr
	}
	response, err := memoryrecall.Search(ctx, memStore, memoryrecall.QueryRequest{
		Workspace:      cfg.WorkspaceID,
		Query:          query,
		QueryEmbedding: queryEmbedding,
		EmbeddingError: embeddingErr,
		VectorContext:  vectorCtx,
		Limit:          limit,
	})
	cancelVectorSearch()
	elapsed := cfg.Clock().Sub(start)
	if err != nil {
		return namedMemoryRecallErrorPack(ctx, cfg, query, elapsed, err), true, contextengine.LaneError{Lane: contextengine.LaneMemory, Err: err}
	}

	pack := a.namedMemoryRecallPack(ctx, cfg, query, response, elapsed)
	return pack, true, nil
}

func (a *ReadOnlyAdapter) embedNamedMemoryQuery(ctx context.Context, memStore storage.MemoryStore, workspaceID, query string) ([]float32, error) {
	embedder, err := semantic.NewEmbedderFromConfig(semantic.ScopeMemory, a.cfg)
	if err != nil {
		return nil, err
	}
	result, err := embedder.Embed(ctx, semantic.EnrichQuery(query))
	if err != nil {
		return nil, err
	}
	if err := memStore.ValidateEmbeddingDimensions(ctx, workspaceID, len(result.Vec)); err != nil {
		return nil, err
	}
	return result.Vec, nil
}

func namedMemoryRecallVectorContext(ctx context.Context) (context.Context, context.CancelFunc) {
	if namedMemoryRecallVectorSearchTimeout <= 0 {
		return ctx, func() {}
	}
	return context.WithTimeout(ctx, namedMemoryRecallVectorSearchTimeout)
}

func (a *ReadOnlyAdapter) namedMemoryGatherPacksFn(statuses []contextengine.ClaimStatus, scope contextengine.MemoryQueryScope, options namedMemoryGatherOptions) contextengine.ContextPackFunc {
	if scope.HasScope() || !contextengine.MemoryQueryAllowsNamedFallback(contextengine.EffectiveMemoryQueryStatuses(statuses, scope)) {
		return nil
	}
	return func(ctx context.Context, workspaceID, query string, limit int) ([]contextengine.EvidencePack, error) {
		cfg := a.laneConfig()
		if workspaceID = strings.TrimSpace(workspaceID); workspaceID != "" {
			cfg.WorkspaceID = workspaceID
		}
		queries := namedMemoryGatherQueries(query, options)
		packs := make([]contextengine.EvidencePack, 0, len(queries))
		seenRefs := map[string]struct{}{}
		var lastErr error
		for _, item := range queries {
			pack, ok, err := a.retrieveNamedMemory(ctx, cfg, item, limit)
			if err != nil {
				lastErr = err
			}
			if !ok || len(pack.Nodes) == 0 {
				continue
			}
			pack.Nodes = dedupeNamedMemoryPackNodes(pack.Nodes, seenRefs)
			if len(pack.Nodes) == 0 {
				continue
			}
			packs = append(packs, pack)
		}
		return packs, lastErr
	}
}

func namedMemoryGatherQueries(query string, options namedMemoryGatherOptions) []string {
	out := make([]string, 0, 6)
	add := func(value string) {
		value = strings.TrimSpace(value)
		if value == "" {
			return
		}
		for _, existing := range out {
			if strings.EqualFold(existing, value) {
				return
			}
		}
		out = append(out, value)
	}
	add(query)
	if !options.CoverageRepair {
		return out
	}
	for _, req := range options.CoverageRequirements {
		if strings.EqualFold(strings.TrimSpace(req.Kind), "answer_slot") {
			continue
		}
		add(strings.TrimSpace(strings.Join(append([]string{req.Label}, req.Terms...), " ")))
		if len(out) >= 6 {
			return out
		}
	}
	for _, evidence := range options.RequiredEvidence {
		add(evidence)
		if len(out) >= 6 {
			return out
		}
	}
	return out
}

func dedupeNamedMemoryPackNodes(nodes []contextengine.EvidenceNode, seen map[string]struct{}) []contextengine.EvidenceNode {
	out := make([]contextengine.EvidenceNode, 0, len(nodes))
	for _, node := range nodes {
		key := strings.TrimSpace(contextengine.FormatEvidenceRef(node.Ref))
		if key == "" {
			key = strings.TrimSpace(node.ID)
		}
		if key == "" {
			continue
		}
		if _, ok := seen[key]; ok {
			continue
		}
		seen[key] = struct{}{}
		out = append(out, node)
	}
	return out
}

func (a *ReadOnlyAdapter) namedMemoryRecallPack(ctx context.Context, cfg contextengine.LaneConfig, query string, response memoryrecall.QueryResponse, elapsed time.Duration) contextengine.EvidencePack {
	packID := cfg.IDGen()
	nodes := make([]contextengine.EvidenceNode, 0, len(response.Entries))
	suppressedLifecycle := 0
	for _, scored := range response.Entries {
		entry := scored.Entry
		if !memoryrecall.QuerySimilarityAllows(scored.Score, query, memoryrecall.DefaultMinSimilarity) {
			continue
		}
		if !memoryrecall.LifecycleAllowsThreshold(entry.LifecycleState, scored.Score, query, memoryrecall.CandidateThresholdForQuery(query)) {
			suppressedLifecycle++
			continue
		}
		refValue := strings.TrimSpace(entry.Name)
		if refValue == "" {
			refValue = strings.TrimSpace(entry.ID)
		}
		if refValue == "" {
			continue
		}
		nodes = append(nodes, contextengine.EvidenceNode{
			ID:          cfg.IDGen(),
			WorkspaceID: cfg.WorkspaceID,
			NodeType:    contextengine.EvidenceNodeTypeMemory,
			Ref: contextengine.EvidenceRef{
				Type:        contextengine.RefTypeNamedMemory,
				Ref:         refValue,
				WorkspaceID: cfg.WorkspaceID,
			},
			Statement:  memoryrecall.NamedEntryText(entry),
			Confidence: clampScore(scored.Score),
			Grounding:  contextengine.GroundingIndexed,
			Metadata: map[string]any{
				"source":          "named_memory",
				"source_profile":  string(contextengine.SourceProfileMemory),
				"source_id":       refValue,
				"memory_id":       entry.ID,
				"memory_type":     entry.Type,
				"path":            namedMemoryEvidencePath(refValue),
				"search_method":   response.Method,
				"score":           scored.Score,
				"lifecycle_state": entry.LifecycleState,
				"review_status":   entry.ReviewStatus,
				"entities":        entry.Entities,
				"keywords":        entry.Keywords,
			},
		})
	}

	pack := contextengine.EvidencePack{
		ID:          packID,
		WorkspaceID: cfg.WorkspaceID,
		Query:       query,
		Lane:        contextengine.LaneMemory,
		Nodes:       nodes,
		Telemetry: contextengine.EvidenceTelemetry{
			DurationMs: elapsed.Milliseconds(),
		},
		Metadata: map[string]any{
			"source":                  "named_memory",
			"search_method":           response.Method,
			"candidate_count":         len(response.Entries),
			"suppressed_by_lifecycle": suppressedLifecycle,
		},
	}
	if response.Hint != "" {
		pack.Metadata["hint"] = response.Hint
	}
	if len(nodes) > 0 {
		_ = recordNamedMemoryRecallPack(ctx, cfg, &pack, len(nodes), elapsed)
	}
	return pack
}

func namedMemoryEvidencePath(refValue string) string {
	refValue = strings.TrimSpace(refValue)
	if refValue == "" {
		return ""
	}
	var b strings.Builder
	lastDash := false
	for _, r := range strings.ToLower(refValue) {
		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '.' || r == '_' {
			b.WriteRune(r)
			lastDash = false
			continue
		}
		if !lastDash {
			b.WriteByte('-')
			lastDash = true
		}
	}
	value := strings.Trim(b.String(), "-")
	if value == "" {
		return ""
	}
	if len(value) > 80 {
		value = strings.TrimRight(value[:80], "-")
	}
	return "memory/" + value
}

func namedMemoryRecallErrorPack(ctx context.Context, cfg contextengine.LaneConfig, query string, elapsed time.Duration, err error) contextengine.EvidencePack {
	pack := contextengine.EvidencePack{
		ID:          cfg.IDGen(),
		WorkspaceID: cfg.WorkspaceID,
		Query:       query,
		Lane:        contextengine.LaneMemory,
		Telemetry: contextengine.EvidenceTelemetry{
			DurationMs: elapsed.Milliseconds(),
		},
		Metadata: map[string]any{
			"source": "named_memory",
			"error":  err.Error(),
		},
	}
	_ = recordNamedMemoryRecallPack(ctx, cfg, &pack, 0, elapsed)
	return pack
}

func recordNamedMemoryRecallPack(ctx context.Context, cfg contextengine.LaneConfig, pack *contextengine.EvidencePack, hitCount int, elapsed time.Duration) error {
	if cfg.Store == nil || pack == nil {
		return nil
	}
	episodeID := cfg.IDGen()
	if pack.Metadata == nil {
		pack.Metadata = map[string]any{}
	}
	pack.Metadata["episode_id"] = episodeID
	_, packErr := cfg.Store.PutEvidencePack(ctx, *pack)
	_, episodeErr := cfg.Store.RecordRetrievalEpisode(ctx, contextengine.RetrievalEpisode{
		ID:          episodeID,
		WorkspaceID: cfg.WorkspaceID,
		Query:       pack.Query,
		Lane:        contextengine.LaneMemory,
		PackID:      pack.ID,
		DurationMs:  elapsed.Milliseconds(),
		HitCount:    hitCount,
		CreatedAt:   cfg.Clock(),
	})
	if packErr != nil {
		return packErr
	}
	return episodeErr
}

