## 1. `internal/intelligence/retrieval/memoryrecall/hyde.go`

```go
package memoryrecall

import (
	"fmt"
	"math"
	"strings"
)

const (
	// MaxHyDEHypotheses caps the number of hypothetical documents generated
	// per query to keep embedding cost bounded.
	MaxHyDEHypotheses = 3
)

// HyDEHypotheses generates deterministic hypothetical answer passages for the
// given query. The hypotheses are meant to be embedded alongside the original
// query to improve recall over named memories whose phrasing diverges from the
// question. The generator is rule-based and does not call an LLM.
func HyDEHypotheses(query string, answerType string) []string {
	query = strings.TrimSpace(query)
	if query == "" {
		return nil
	}
	if answerType == "" {
		answerType = classifyHyDEAnswerType(query)
	}
	hypotheses := hydeHypothesesForType(query, answerType)
	if len(hypotheses) > MaxHyDEHypotheses {
		hypotheses = hypotheses[:MaxHyDEHypotheses]
	}
	return hypotheses
}

func classifyHyDEAnswerType(query string) string {
	q := " " + strings.ToLower(strings.TrimSpace(query)) + " "
	switch {
	case strings.Contains(q, " how many ") || strings.Contains(q, " count ") || strings.Contains(q, " number of "):
		return "count"
	case strings.Contains(q, " where "):
		return "location"
	case strings.Contains(q, " how long ") || strings.Contains(q, " duration ") || strings.Contains(q, " commute "):
		return "duration"
	case strings.Contains(q, " when ") || strings.Contains(q, " date ") || strings.Contains(q, " latest ") || strings.Contains(q, " most recent "):
		return "temporal"
	case strings.Contains(q, " list ") || strings.Contains(q, " which ") || (strings.Contains(q, " what ") && containsAnyHyDETerm(q, " items ", " things ", " products ", " places ")):
		return "list"
	default:
		return "fact"
	}
}

func containsAnyHyDETerm(s string, substrs ...string) bool {
	for _, substr := range substrs {
		if strings.Contains(s, substr) {
			return true
		}
	}
	return false
}

func hydeHypothesesForType(query, answerType string) []string {
	switch answerType {
	case "count":
		return []string{
			"The count is <number>.",
			"There are <number> matching items for " + query + ".",
		}
	case "list":
		return []string{
			"The items are: <list>.",
			"A complete list for " + query + " includes the following items.",
		}
	case "location":
		return []string{
			"The location is <place>.",
			"It is located at <place> for " + query + ".",
		}
	case "duration":
		return []string{
			"The duration is <duration>.",
			"It takes <duration> for " + query + ".",
		}
	case "temporal":
		return []string{
			"The date is <date>.",
			"It happened on <date> for " + query + ".",
		}
	default:
		return []string{
			"The answer to " + query + " is <answer>.",
			query + " is <answer>.",
		}
	}
}

// CombineEmbeddings returns the mean-pooled combination of the input
// embeddings. All embeddings must have the same dimension. Callers should
// normalize the result if the downstream consumer expects unit vectors.
func CombineEmbeddings(embeddings [][]float32) ([]float32, error) {
	if len(embeddings) == 0 {
		return nil, fmt.Errorf("no embeddings to combine")
	}
	dim := len(embeddings[0])
	if dim == 0 {
		return nil, fmt.Errorf("empty embedding")
	}
	combined := make([]float32, dim)
	for _, emb := range embeddings {
		if len(emb) != dim {
			return nil, fmt.Errorf("embedding dimension mismatch: %d vs %d", len(emb), dim)
		}
		for i, v := range emb {
			combined[i] += v
		}
	}
	invN := 1.0 / float64(len(embeddings))
	for i := range combined {
		combined[i] = float32(float64(combined[i]) * invN)
	}
	return combined, nil
}

// NormalizeEmbedding L2-normalizes an embedding in place and returns it.
func NormalizeEmbedding(emb []float32) []float32 {
	var sum float64
	for _, v := range emb {
		sum += float64(v) * float64(v)
	}
	if sum == 0 {
		return emb
	}
	norm := math.Sqrt(sum)
	for i := range emb {
		emb[i] = float32(float64(emb[i]) / norm)
	}
	return emb
}
```

