func buildSynthesisPrompt(query string, candidatePaths, evidenceRefs, acceptedLedgerEvidence, phaseNotes []string) string {
	var b strings.Builder
	b.WriteString(strings.TrimSpace(query))
	b.WriteString("\n\nWrite the final answer using only the verified evidence from the staged phases.")

	// Temporal/duration questions need explicit date extraction and interval
	// arithmetic guidance. The classifier here only enriches the prompt text;
	// it does not route, suppress, or otherwise change runtime behavior.
	if answerType := classifySynthesisAnswerType(query); answerType == "duration" || answerType == "temporal" {
		b.WriteString("\n\nThis question asks about time or duration. Follow these steps exactly:")
		b.WriteString("\n1. Extract every date, year, month, or day expression mentioned in the accepted ledger evidence.")
		b.WriteString("\n2. If two or more dates are present, compute the difference between them in days (or in years if days cannot be determined).")
		b.WriteString("\n3. State the final answer as a number of days or years. Do not say you cannot calculate if the evidence contains the necessary dates.")
		b.WriteString("\n4. Show the two dates you compared and the resulting interval.")
	}

	if len(candidatePaths) > 0 {
		b.WriteString("\nCandidate paths: ")
		b.WriteString(strings.Join(shortenRefs(candidatePaths, 10), ", "))
	}
	if len(evidenceRefs) > 0 {
		b.WriteString("\nDiagnostic surfaced evidence refs, not standalone factual support: ")
		b.WriteString(strings.Join(shortenRefs(evidenceRefs, 12), ", "))
	}
	if len(acceptedLedgerEvidence) > 0 {
		b.WriteString("\nAccepted ledger evidence:\n")
		for _, row := range acceptedLedgerEvidence {
			b.WriteString("- ")
			b.WriteString(truncateRLMText(row, 320))
			b.WriteString("\n")
		}
	} else if len(evidenceRefs) > 0 {
		b.WriteString("\nNo accepted ledger evidence was collected. Do not answer from surfaced or rejected evidence; state that verified evidence is insufficient.")
	}
	return b.String()
}

func classifySynthesisAnswerType(query string) string {
	q := " " + strings.ToLower(strings.TrimSpace(query)) + " "
	switch {
	case strings.Contains(q, " how long ") ||
		strings.Contains(q, " duration ") ||
		strings.Contains(q, " commute ") ||
		strings.Contains(q, " how many days ") ||
		strings.Contains(q, " how many years "):
		return "duration"
	case strings.Contains(q, " when ") ||
		strings.Contains(q, " date ") ||
		strings.Contains(q, " latest ") ||
		strings.Contains(q, " most recent ") ||
		strings.Contains(q, " how long ago "):
		return "temporal"
	default:
		return "fact"
	}
}
```

