Good news — `extractEvidenceLedgerValues` already extracts dates into `answer_values.dates`. The issue is the synthesis prompt doesn't tell the model to use those pre-extracted dates; it tries to parse them from free text and gets them wrong.

The fix: have `buildSynthesisPrompt` collect the dates from `acceptedLedgerEvidence` rows and list them explicitly, so the model only has to compute the interval.

## Patch for `internal/rlm/llm_runner.go`

### Add pattern near other regexes

```go
var synthesisDatePattern = regexp.MustCompile(`(?i)\b(?:jan|feb|mar|apr|may|jun|jul|aug|sep|sept|oct|nov|dec)[a-z]*\s+\d{1,2}(?:,\s*\d{4})?|\d{4}-\d{2}-\d{2}|\d{1,2}/\d{1,2}/\d{2,4}\b`)
```

### Replace `buildSynthesisPrompt`

```go
func buildSynthesisPrompt(query string, candidatePaths, evidenceRefs, acceptedLedgerEvidence, phaseNotes []string) string {
	var b strings.Builder
	b.WriteString(strings.TrimSpace(query))
	b.WriteString("\n\nWrite the final answer using only the verified evidence from the staged phases.")

	answerType := classifySynthesisAnswerType(query)
	if answerType == "duration" || answerType == "temporal" {
		b.WriteString("\n\nThis question asks about time or duration. Follow these steps exactly:")
		b.WriteString("\n1. Use only the dates already extracted in the accepted ledger evidence (look for the date phrases).")
		b.WriteString("\n2. If two or more dates are present, compute the difference between them in days.")
		b.WriteString("\n3. State the final answer as a number of days. Do not say you cannot calculate if dates are present.")
		if dates := collectSynthesisDates(acceptedLedgerEvidence); len(dates) >= 2 {
			b.WriteString("\n4. The evidence contains these dates: ")
			b.WriteString(strings.Join(dates, ", "))
			b.WriteString(". Compute the interval in days between them and state the result.")
		}
	}

	if len(candidatePaths) > 0 {
		b.WriteString("\nCandidate paths: ")
		b.WriteString(strings.Join(shortenRefs(candidatePaths, 10), ", "))
	}
	if len(evidenceRefs) > 0 {
		b.WriteString("\nDiagnostic surfaced evidence refs, not standalone factual support: ")
		b.WriteString(strings.Join(shortenRefs(evidenceRefs, 12), ", "))
	}
	if len(acceptedLedgerEvidence) > 0 {
		b.WriteString("\nAccepted ledger evidence:\n")
		for _, row := range acceptedLedgerEvidence {
			b.WriteString("- ")
			b.WriteString(truncateRLMText(row, 320))
			b.WriteString("\n")
		}
	} else if len(evidenceRefs) > 0 {
		b.WriteString("\nNo accepted ledger evidence was collected. Do not answer from surfaced or rejected evidence; state that verified evidence is insufficient.")
	}
	return b.String()
}
```

### Add helper

```go
func collectSynthesisDates(rows []string) []string {
	seen := make(map[string]struct{})
	out := make([]string, 0, len(rows)*2)
	for _, row := range rows {
		for _, match := range synthesisDatePattern.FindAllString(row, -1) {
			match = strings.TrimSpace(match)
			if match == "" {
				continue
			}
			key := strings.ToLower(match)
			if _, ok := seen[key]; ok {
				continue
			}
			seen[key] = struct{}{}
			out = append(out, match)
		}
	}
	return out
}
```

