		"path:y: visited Met on Oct 22, 2023; answer_values={dates: [Oct 22, 2023]}",
	}
	got := collectSynthesisDates(input)
	if len(got) != 2 {
		t.Fatalf("got %d dates: %v", len(got), got)
	}
	want0 := "Oct 15, 2023"
	want1 := "Oct 22, 2023"
	if !strings.EqualFold(got[0], want0) || !strings.EqualFold(got[1], want1) {
		t.Fatalf("got %v, want [%s %s]", got, want0, want1)
	}
}
