func renderSession(messages []Message, sessionDate string) string {
	var b strings.Builder
	sessionDate = strings.TrimSpace(sessionDate)
	if sessionDate != "" {
		b.WriteString("Session date: ")
		b.WriteString(sessionDate)
		b.WriteString("\n")
	}
	if len(messages) == 0 {
		return b.String()
	}
	b.WriteString(fmt.Sprintf("Turns: %d\n", len(messages)))
	for i, msg := range messages {
